window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_043"]={"n":"佘翔","dyn":"明","poems":[{"t":"题栖禅寺","f":"五言绝句","c":["片片归林鸟，微微出寺钟。","僧门掩秋色，明月挂高松。"]},{"t":"秋日还故园","f":"七言律诗","c":["渡水登山到草堂，田家稻黍喜新尝。","墙边薜荔秋多雨，池上芙蓉夜有霜。","看竹每寻扶老杖，借书先录养生方。","归来自笑白头客，况复江南是故乡。"]},{"t":"三洲十景 其一 烟墩孤树","f":"五言绝句","c":["海上旧烟垒，频年罢举烽。","但有孤树影，带月舞龙钟。"]},{"t":"三洲十景 其二 海寺疏钟","f":"五言绝句","c":["墟里黄昏候，投林鸟雀哀。","渡头钟隐隐，风送普陀来。"]},{"t":"三洲十景 其三 白水渔歌","f":"五言绝句","c":["一水接沧溟，六鳌秋可钓。","试听欸乃歌，吾亦发长啸。"]},{"t":"三洲十景 其四 沧洲樵隐","f":"五言绝句","c":["东海涌三洲，负薪堪自老。","吾生澹荡人，更欲搴瑶草。"]},{"t":"三洲十景 其五 六桥夜月","f":"五言绝句","c":["彷佛西湖上，烟波锁六桥。","美人明月夜，好泛木兰桡。"]},{"t":"三洲十景 其六 三江雪浪","f":"五言绝句","c":["海门烟雾深，忽见秋涛起。","欲折扶桑枝，乘潮去万里。"]},{"t":"三洲十景 其七 榕阴连陌","f":"五言绝句","c":["积翠尽阴阴，风吹十里响。","上栖白鹭群，下映青苔壤。"]},{"t":"三洲十景 其八 涧水流花","f":"五言绝句","c":["淙淙涧里水，不啻鸭头绿。","有时流落花，疑是桃源曲。"]},{"t":"三洲十景 其九 平畴三塔","f":"五言绝句","c":["宝塔镇东方，亭亭三鸑鷟。","云中挂暮蟾，海上射朝旭。"]},{"t":"三洲十景 其十 芳树孤台","f":"五言绝句","c":["嘉树郁成阴，孤台眺苍莽。","长笑似苏门，白云自来往。"]},{"t":"玉阶怨","f":"五言绝句","c":["玉阶无人行，监宫日日扫。","夜来望四星，白露沾秋草。"]},{"t":"葛仙井","f":"五言绝句","c":["昔时炼液人，凿井湖山侧。","即今井中泉，犹带丹霞色。"]},{"t":"出郭","f":"五言绝句","c":["出郭期无事，看花转不閒。","夕阳低众壑，水底见青山。"]},{"t":"少年行","f":"五言绝句","c":["九衢驰马去，三辅斗鸡来。","不必通名姓，金吾夜钥开。"]},{"t":"寄游宗谦","f":"五言绝句","c":["一曳王门裾，风流工赋雪。","不知楚醴筵，犹为穆生设。"]},{"t":"秋夜有怀","f":"五言绝句","c":["夕露滴疏桐，月下鸣双杵。","清宵耿不寐，美人何处所。"]},{"t":"采石怀古","f":"五言绝句","c":["峨峨采石矶，下有蛟龙窟。","不见骑鲸人，波心堕明月。"]},{"t":"望九华山","f":"五言绝句","c":["多少风波客，劳歌棹往还。","眼中青似黛，惟有九华山。"]},{"t":"荻港晚泊","f":"五言绝句","c":["挂席东南行，青山望迢忽。","日暮寒潮生，维舟对孤月。"]},{"t":"舟中对月","f":"五言绝句","c":["东风吹片雨，遥溯大江流。","可是鸱夷子，乾坤一叶舟。"]},{"t":"宿桃叶渡","f":"五言绝句","c":["片月冷黄昏，家家静掩门。","避秦人不见，山犬吠江村。"]},{"t":"长干行","f":"五言绝句","c":["莫愁貌如花，生长长干里。","嫁与远游郎，愁风复愁水。"]},{"t":"晓寒即事","f":"五言绝句","c":["昨夜风霜冷，孤衾愁杀人。","朝来看两鬓，种种已如银。"]},{"t":"阊门怀古","f":"五言绝句","c":["城下多春草，馆娃何处寻。","惟有阊门水，前朝流至今。"]},{"t":"吴山晚眺","f":"五言绝句","c":["雨歇江天迥，凭高见午潮。","紫阳云乍起，彷佛赤城标。"]},{"t":"苏小小墓","f":"五言绝句","c":["粉黛何年没，春风土一抔。","香魂幻蝴蝶，疑逐夜花来。"]},{"t":"投野寺宿","f":"五言绝句","c":["不见东林寺，但闻隔水钟。","溪深桥复断，片月挂孤峰。"]},{"t":"春日怀归","f":"五言绝句","c":["谷口啭莺声，春风发杨柳。","萧条万里人，孤帆伤白首。"]},{"t":"怀陈振旺","f":"五言绝句","c":["孟公倜傥人，风流传尺牍。","云树色苍茫，空穷千里目。"]},{"t":"江上阻风","f":"五言绝句","c":["系缆此江浒，风狂不作雨。","木叶晚萧萧，扁舟谁与语。"]},{"t":"夜月荷香","f":"五言绝句","c":["一曲沧浪水，盈盈片月光。","湖边香不散，玉女试霓裳。"]},{"t":"古别离","f":"五言绝句","c":["问君何所之，未语泪先落。","宁跨茅家龙，莫采刘郎药。"]},{"t":"怀友 其一","f":"五言绝句","c":["着屐步苍苔，萧然尘事少。","美人来不来，隔竹闻啼鸟。"]},{"t":"怀友 其二","f":"五言绝句","c":["闭户读南华，人踪幽径绝。","徙倚有所思，一片东山月。"]},{"t":"闺词 其一","f":"五言绝句","c":["春风入绣帏，花气入罗衣。","刺得鸳鸯枕，待郎几日归。"]},{"t":"闺词 其二","f":"五言绝句","c":["郎戍潇关去，别离何太久。","塞雁秋来多，见郎寄书否。"]},{"t":"宫词","f":"五言绝句","c":["待月立金阶，露冷罗衣薄。","徙倚玉阑干，秋风吹帘幕。"]},{"t":"听鸟","f":"五言绝句","c":["禅房钟乍歇，古术鸟初啼。","催醒还家梦，依然在虎溪。"]},{"t":"侠客","f":"五言绝句","c":["都市知名姓，横行借报仇。","酣歌易水去，那问大刀头。"]},{"t":"古意","f":"五言绝句","c":["窈窕卢家妇，当窗理针线。","含情步花间，羞见双飞燕。"]},{"t":"湖心亭即事","f":"五言绝句","c":["平湖开一镜，日暮繫楼船。","酒似移盘石，歌疑唱采莲。"]},{"t":"九日饮酒肆","f":"五言绝句","c":["他乡逢素节，何处觅黄花。","白发登高懒，将钱向酒家。"]},{"t":"卧龙山怀古","f":"五言绝句","c":["欲览会稽城，试上龙山顶。","越王不复来，万家春树冷。"]},{"t":"自君之出矣","f":"五言绝句","c":["自君之出矣，铅华不复理。","思君如浮云，日逐东流水。"]},{"t":"大佛寺夜坐","f":"五言绝句","c":["片月挂遥岑，荡漾湖波里。","山僧犹未眠，谡谡松风起。"]},{"t":"七夕风雨有怀","f":"五言绝句","c":["咫尺不可见，夷门风雨多。","一水非银汉，无梁当奈何。"]},{"t":"挽徐子瞻明府 其一","f":"五言绝句","c":["乘化飘然去，言登紫府班。","石麟天上物，元不住人间。"]},{"t":"挽徐子瞻明府 其二","f":"五言绝句","c":["白云随出没，精气化为龙。","纵有陈蕃榻，南州不可逢。"]},{"t":"挽徐子瞻明府 其三","f":"五言绝句","c":["北邙歌薤露，列宿失郎官。","箧里留中论，芳名并建安。"]},{"t":"挽徐子瞻明府 其四","f":"五言绝句","c":["修文归地下，三径长蓬蒿。","剩有河东凤，钟山日夜号。"]},{"t":"江岸次舟有怀","f":"五言绝句","c":["秋风江上来，吹转东流水。","停桡有所思，月白长千里。"]},{"t":"怀南山寄澹上人","f":"五言绝句","c":["出郭饶山水，凤凰隐化城。","别来风雨夜，梦断虎溪声。"]},{"t":"题酒家仝钱季善作","f":"五言绝句","c":["解下鹔鹴裘，恰贳酒一斗。","笑问酒家胡，有客如此否。"]},{"t":"春晓戏柬张幼于","f":"五言绝句","c":["蚕事犹未起，登楼理晓妆。","双眉元似黛，不用画张郎。"]},{"t":"山阴道上风雨","f":"五言绝句","c":["东郡多山水，高踪想古人。","欲歌招隐曲，风雨暗相亲。"]},{"t":"病中喜景受宗振至","f":"五言绝句","c":["莺花愁不废，药石病难除。","二仲劳相过，春风满敝庐。"]},{"t":"古别离二首 其一","f":"五言绝句","c":["南海有明珠，光洁还如昨。","君心谅不移，所嗟妾命薄。"]},{"t":"古别离二首 其二","f":"五言绝句","c":["飘飘杨白花，随风无定止。","一片别郎心，可以照秋水。"]},{"t":"西岩杂咏 其一 白云窝","f":"五言绝句","c":["卜筑青山下，白云任往还。","多情花下鸟，相对语关关。"]},{"t":"西岩杂咏 其二 钓月矶","f":"五言绝句","c":["直钩何用钓，待月扫渔矶。","鸥鸟双双下，怜人久息机。"]},{"t":"西岩杂咏 其三 一鉴塘","f":"五言绝句","c":["一镜无浮云，澄波彻下上。","但得会心处，何须濠濮想。"]},{"t":"西岩杂咏 其四 芙蓉池","f":"五言绝句","c":["芙蓉照秋水，湘女集为裳。","忽闻仙佩响，月下挹群芳。"]},{"t":"西岩杂咏 其五 桃花源","f":"五言绝句","c":["桃花然小坞，恍惚武陵源。","远浦渔歌入，前林鸟语喧。"]},{"t":"西岩杂咏 其六 赤壁","f":"五言绝句","c":["赤壁临烟水，仙人鞭石来。","清风来水面，荡漾斗牛洄。"]},{"t":"西岩杂咏 其七 鹤径","f":"五言绝句","c":["元鹤栖幽径，声鸣达九天。","会心知万里，暂寄百花前。"]},{"t":"西岩杂咏 其八 鹿门","f":"五言绝句","c":["圣主非熊梦，丈人御鹿归。","苍生多属望，且莫掩柴扉。"]},{"t":"西岩杂咏 其九 荔圃","f":"五言绝句","c":["荔火明玄圃，枝头紫玉团。","欲苏司马渴，试进水晶盘。"]},{"t":"西岩杂咏 其十 留仙岩","f":"五言绝句","c":["层岩凌北斗，东望俯蓬瀛。","为有三珠树，长留子晋笙。"]},{"t":"西岩杂咏 其十一 翠云台","f":"五言绝句","c":["芳树接云烟，孤台半接天。","八公自来往，诗咏小山篇。"]},{"t":"西岩杂咏 其十二 悠然亭","f":"五言绝句","c":["一遂初衣心，逍遥无辙迹。","时对南山云，悠然此俱寂。"]},{"t":"西岩杂咏 其十三 碧山堂","f":"五言绝句","c":["学士碧山隐，焚鱼问草堂。","千载云龙会，为霖意不忘。"]},{"t":"西岩杂咏 其十四 朝爽轩","f":"五言绝句","c":["白露湛千秋，枝头鸟声响。","阳乌海上来，亭榭生秋爽。"]},{"t":"西岩杂咏 其十五 夕嘉楼","f":"五言绝句","c":["晚照挂松萝，岩居乐事多。","丛林归鸟集，远寺暮钟和。"]},{"t":"西岩杂咏 其十六 仙居楼","f":"五言绝句","c":["楼阁悬青汉，乘风蹑斗墟。","空中鸾鹤下，此地即仙居。"]},{"t":"西岩杂咏 其十七 灵源洞","f":"五言绝句","c":["灵源开宝洞，瑶草长阑干。","一授刀圭诀，颜容驻渥丹。"]},{"t":"西岩杂咏 其十八 琼液泉","f":"五言绝句","c":["为问琼浆窟，何如太液长。","临流倾玉碗，高枕傲羲皇。"]},{"t":"西岩杂咏 其十九 茗园","f":"五言绝句","c":["艺得芳园茗，采将谷雨时。","樵青扫竹煮，一碗一篇诗。"]},{"t":"西岩杂咏 其二十 秫田","f":"五言绝句","c":["帝宠归农日，閒犁种秫田。","但教多酿酒，乐圣且称贤。"]},{"t":"题林德夫乐丘 其一 梅坡真隐","f":"五言绝句","c":["梅花清似雪，缥缈白云间。","不有神仙住，谁传姑射山。"]},{"t":"题林德夫乐丘 其二 望海苍岩","f":"五言绝句","c":["高蹈营丘壑，林峦骋目初。","峨眉云变幻，海气直凌虚。"]},{"t":"题林德夫乐丘 其三 瑶泉流碧","f":"五言绝句","c":["千年流不竭，谷口气氤氛。","莫是神龙窟，灵湫泻白云。"]},{"t":"题林德夫乐丘 其四 拟谢公墩","f":"五言绝句","c":["古木参天迥，青山载酒多。","谢公墩可拟，词客盛年何。"]},{"t":"题林德夫乐丘 其五 叠玉山房","f":"五言绝句","c":["夜梦昆山玉，朝名有美堂。","但看松竹色，何处不琳琅。"]},{"t":"题林德夫乐丘 其六 刘安丛桂","f":"五言绝句","c":["山似淮南秀，人歌丛桂篇。","莫论今与昔，异代总登仙。"]},{"t":"题林德夫乐丘 其七 松月夜窗","f":"五言绝句","c":["松斋零露滴，夜坐思泠然。","一诵襄阳句，山窗月色偏。"]},{"t":"题林德夫乐丘 其八 春草池塘","f":"五言绝句","c":["眷此栖真地，高深辟化工。","池塘春草梦，不减谢家风。"]},{"t":"题林德夫东山别墅 其一","f":"五言绝句","c":["偃蹇歌招隐，栖迟老岁华。","世情从燕雀，吾道自龙蛇。"]},{"t":"题林德夫东山别墅 其二","f":"五言绝句","c":["猿鸟山中侣，松萝物外情。","看花多藉草，恰恰听流莺。"]},{"t":"题林德夫东山别墅 其三","f":"五言绝句","c":["松下时调鹤，溪边日钓鱼。","孤山林处士，封禅总无书。"]},{"t":"题林德夫东山别墅 其四","f":"五言绝句","c":["眷此栽花地，而多种秫田。","桔槔偏不用，鼓腹乐尧天。"]},{"t":"题林德夫东山别墅 其五","f":"五言绝句","c":["入林无俗物，爱客有深怀。","谁得逍遥趣，风吹海月来。"]},{"t":"题林德夫东山别墅 其六","f":"五言绝句","c":["山气冷疏牖，墟烟淡远村。","桑麻与鸡犬，彷佛武陵源。"]},{"t":"题林德夫东山别墅 其七","f":"五言绝句","c":["群峰青似黛，一水碧如油。","但得会心处，何须到十洲。"]},{"t":"题林德夫东山别墅 其八","f":"五言绝句","c":["芳洁纫兰佩，离披咏桂丛。","谢家春草梦，无日不诗筒。"]},{"t":"题林德夫东山别墅 其九","f":"五言绝句","c":["花气朝侵榻，松风夜拂琴。","庭前梧与竹，鸾凤自为林。"]},{"t":"题林德夫东山别墅 其十","f":"五言绝句","c":["白发甘肥遁，青山狎隐沦。","试看朝市客，若个是閒人。"]},{"t":"题胡参军池亭 其一","f":"五言绝句","c":["白云澹忘归，川上气萧爽。","鱼鸟来亲人，居然濠濮想。"]},{"t":"题胡参军池亭 其二","f":"五言绝句","c":["抱瓮似汉阴，地僻无车马。","白鸥海上来，日对忘机者。"]},{"t":"重阳前一日送周元孚还楚 其一","f":"五言绝句","c":["令节逼重九，归期及暮寒。","风霜摇落候，莫遣客衣单。"]},{"t":"重阳前一日送周元孚还楚 其二","f":"五言绝句","c":["篱下菊盈把，尊前客尽欢。","讵容风雨妒，新月满长安。"]},{"t":"重阳前一日送周元孚还楚 其三","f":"五言绝句","c":["南国宦犹薄，西陵梦未残。","君家湘水近，行矣纫秋兰。"]},{"t":"题友人池亭 其一","f":"五言绝句","c":["花竹散清阴，孤亭苍翠里。","坐来百虑消，彷佛临秋水。"]},{"t":"题友人池亭 其二","f":"五言绝句","c":["高阁霞为幔，参差花影重。","斗间真气在，知有抱珠龙。"]},{"t":"题友人池亭 其三","f":"五言绝句","c":["池塘开十亩，流水漾桃花。","但得如泥醉，何须问习家。"]},{"t":"对菊吟","f":"五言绝句","c":["黄花香裛露，采采满东篱。","不有陶元亮，谁来倒酒卮。"]},{"t":"采莲曲","f":"五言绝句","c":["澄澄若耶溪，盈盈采莲女。","将花比玉颜，溪上自容与。"]},{"t":"壶庄八咏 其一 云庄缥缈","f":"五言绝句","c":["素性耽林丘，卜此栖杖屦。","一啸洞中天，白云任来去。"]},{"t":"壶庄八咏 其二 石洞崔嵬","f":"五言绝句","c":["灵岩类削成，不结茅为屋。","欲觅炼丹人，逍遥此辟谷。"]},{"t":"壶庄八咏 其三 翠壶倒枕","f":"五言绝句","c":["借来壶作枕，笑傲足烟霞。","莫著籓篱想，空中纳九华。"]},{"t":"壶庄八咏 其四 兰波环带","f":"五言绝句","c":["兰津环一带，万古自春秋。","时发沧浪咏，矶头濯足流。"]},{"t":"壶庄八咏 其五 石拱三台","f":"五言绝句","c":["昔人云此石，原应天中宿。","可是魁三象，山间长孕秀。"]},{"t":"壶庄八咏 其六 霞映赤城","f":"五言绝句","c":["隐隐梅台外，雉垣入眼赊。","仙风如可御，咫尺赤城霞。"]},{"t":"壶庄八咏 其七 一峰中立","f":"五言绝句","c":["长随鹿豕群，有时瞻太乙。","顿觉振衣宽，扶桑低海日。"]},{"t":"壶庄八咏 其八 双鹤飞翀","f":"五言绝句","c":["野趣偏耽鹤，从容坐翠微。","云霄万里迥，健翮任高飞。"]},{"t":"长安道","f":"五言绝句","c":["何处可消忧，长安高酒楼。","楼前双柳树，好系紫骅骝。"]},{"t":"雨后吟","f":"五言绝句","c":["夜来北窗雨，萧萧竹偃扉。","朝望城头山，白云湿不飞。"]},{"t":"望囊山","f":"五言绝句","c":["松林度鸟急，鹫岭巢云低。","欲问莲花社，斜阳过虎溪。"]},{"t":"催牡丹","f":"五言绝句","c":["春色已平分，名花犹未吐。","把酒一酬之，我歌花且舞。"]},{"t":"饮兰亭","f":"五言绝句","c":["竹树满山阴，前贤迹未扫。","试流曲水觞，醉藉王孙草。"]},{"t":"谒禹庙","f":"五言绝句","c":["丹青留日月，辇道积莓苔。","王气千秋尽，犹传玉帛来。"]},{"t":"湘妃怨","f":"五言绝句","c":["九嶷何处是，玉辇几时过。","千秋悲帝子，竹上泪痕多。"]},{"t":"别马君 其一","f":"五言绝句","c":["斗酒江头别，相看击筑歌。","长江流不尽，离恨较谁多。"]},{"t":"别马君 其二","f":"五言绝句","c":["高才君倚马，落魄我歌鱼。","相劝加餐饭，无忘尺素书。"]},{"t":"班媫妤","f":"五言绝句","c":["片月照金闺，纨扇不堪把。","珠帘上玉钩，霜覆鸳鸯瓦。"]},{"t":"古诗 其一","f":"五言古诗","c":["合浦产明珠，澧泽茁芳草。","褰裳欲采之，将以遗所好。","所好隔天涯，戚戚伤怀抱。","岁寒雨雪多，游子悲远道。","思君重踌躇，一夜令人老。"]},{"t":"古诗 其二","f":"五言古诗","c":["盈盈三五月，流辉入我帷。","中夜起徬徨，忧心当告谁。","白露涂中庭，寒螀夕鸣悲。","岂无心所欢，千里邈音徽。","仰视雁南翔，俯盻庭柯飞。","漫漫兹长夜，涕泪沾裳衣。"]},{"t":"古诗 其三","f":"五言古诗","c":["百年何奄忽，燕乐当及时。","斗酒娱心意，厚薄非所知。","美人朝握手，言笑生光辉。","风波一失所，嘉会安可期。","逝者日以远，来者日以稀。","营营而惜费，无乃贤达嗤。"]},{"t":"古诗 其四","f":"五言古诗","c":["女萝何袅袅，杨柳何依依。","皎皎谁家妇，罗绮媚春晖。","妆成妒桃李，流涕倚双扉。","荡子新婚别，三年行不归。","青春嗟自老，红颜亦已非。","俯仰切中怀，何以解渴饥。"]},{"t":"杂诗 其一","f":"五言古诗","c":["白雪何飘飘，游子多离忧。","美人娇如花，娥娥临青楼。","佳期竟寂寞，蹉跎若河流。","河流漫浩浩，相思令人老。","时物有如期，秉烛苦不早。"]},{"t":"杂诗 其二","f":"五言古诗","c":["今夕复何夕，皎皎明月光。","酌酒登高楼，岂不怀故乡。","欲驾车无輗，欲济河无航。","仰视云汉间，迢迢参与商。","悲风西北来，越鸟东南翔。","援琴不成曲，清泪沾衣裳。"]},{"t":"同郑观察郑明府泛舟徐潭兼送陈宪副之浙中","f":"五言古诗","c":["载酒泛青溪，溪流清如醑。","佳客满华筵，方舟自容与。","鸥鹭散沙汀，原畴被禾黍。","盘礴绿阴间，衔杯避烦暑。","慷慨一行歌，铿然振大吕。","兴剧恣猖狂，情深忘尔汝。","月白且迥舟，离思纷如绪。","伊人济川才，而我烟霞侣。","握手且为欢，浮生俱逆旅。","愿宝金石声，云霄日延伫。"]},{"t":"题四皓图为黄山人全之寿","f":"五言古诗","c":["秦威煽六合，四贤隐商山。","紫芝何霭霭，采之驻红颜。","岂不怀唐虞，世远不可攀。","隆准既兴刘，求之且闭关。","皭然义不辱，心与白云间。","一朝入汉庭，侍燕伟衣冠。","片言成羽翼，宗社赖以安。","伊人韬至德，卷舒若转丸。","处世合如此，果哉何足难。","黄公千载后，风流继考槃。","既探黄石略，亦炼紫金丹。","逃名遵芳躅，肆志托飞翰。","明时终抱璞，宁愧硕人宽。"]},{"t":"赵仁甫邀登越王山同王汝存马从甫林天迪赋","f":"五言古诗","c":["东风吹微和，古道生芳草。","蹇余困旅人，戚戚萦怀抱。","朝来听鸣禽，登高谐所好。","柳色郁黄金，春衣试鲁缟。","款款罄深杯，翩翩裁丽藻。","握手且为欢，浮生悲易老。","曼倩隐金门，安期栖海岛。","仙分各有宜，愿言长自保。"]},{"t":"赠朱开府 其一","f":"五言古诗","c":["三山控闽服，崔嵬开柏府。","懋德重保釐，为宪资文武。","惟公应名世，建牙莅兹土。","灵秀浚滇中，羽仪振畿辅。","寅亮踵毕公，休声迈吉甫。","分陕嘉惠翔，巍然握绣斧。"]},{"t":"赠朱开府 其二","f":"五言古诗","c":["凤凰毛羽奇，松柏坚贞峙。","秉性既清高，摧挫何能倚。","岳伯非不荣，弃之若敝屣。","劲节耸朝绅，令闻裨国是。","简在出帝心，家食不遑起。","王道固荡平，得兴君子理。"]},{"t":"赠朱开府 其三","f":"五言古诗","c":["貔貅肃千队，风云阵八方。","鲸鲲息吹浪，一望通扶桑。","神武沛瀚渤，经略毖封疆。","既已廑未雨，兼之危复隍。","千村屏狐鼠，八郡屹金汤。","铙歌与壤吹，洋洋达建章。"]},{"t":"赠朱开府 其四","f":"五言古诗","c":["兰台昼馀暇，艺苑托深心。","撷英朝华圃，摭实夕秀林。","式庐礼段木，草檄资陈琳。","淩烟勒洪阀，雄风披素襟。","垂老沐德化，况仰龙门深。","愧无山水奏，延赏和知音。"]},{"t":"袁明府招登莲花峰","f":"五言古诗","c":["托乘出城闉，眷言丘壑美。","桑柘迷术阡，园林错山趾。","芳树烟中攒，怪石岩巅峙。","径仄步纡回，亭幽随至止。","萝谷啸猕猴，松岑萦葛藟。","丹壁倩神扶，翠屏役鬼徙。","仰观鸟篆荒，俯视虹桥迤。","竹影散轻飙，榕阴逗晴晷。","快矣坐青林，陶然命绿蚁。","远水泛仙凫，空山怀石髓。","暮霭迎炎凉，林花簇朱紫。","挥麈言弥玄，秉烛欢未已。","岳莲气荡胸，陇麦歌盈耳。","岘首慕羊公，勒石齐芳轨。","伊余汗漫游，庶几若蓬累。","即景恣雕搜，将无惭巴里。"]},{"t":"秋夜书怀","f":"五言古诗","c":["一叶下高梧，随风无所托。","夜静寒蝉鸣，凉飔振寥廓。","感此重伤心，流光何相薄。","世路颇险巇，人心生荆棘。","骑鹤缑氏山，网罗安可得。"]},{"t":"魏贞女诗","f":"五言古诗","c":["烛烛空中月，没且含光辉。","猗猗谷中兰，芬馨死不移。","温温魏氏女，皎皎琼树姿。","既娴内则训，亦诵柏舟诗。","伊昔聘林家，皓首以为期。","君子溘朝露，吁天涕涟洏。","匍匐奔其丧，相殉分所宜。","高堂未展谒，况在天一涯。","罗帷为谁设，膏沭为谁施。","妯娌纷喋喋，宁知我心悲。","水浆不入口，焉问渴与饥。","一朝复一夕，视死甘如饴。","从容下九原，岂曰生结缡。","但作连理树，一抔土相依。","百卉媚春阳，霜露且先萎。","何如松与柏，郁郁岁寒时。","嗟嗟魏氏女，贞心迈等夷。","共姜千载后，芳名史并垂。"]},{"t":"贺朱母寿诗","f":"五言古诗","c":["佳气集高堂，有萱匝金芝。","萱分本忘忧，芝亦日华滋。","春风方骀荡，青鸟来瑶池。","眷言阿母寿，跪进九霞卮。","珍羞罗芬芬，丝竹吹参差。","婺彩射南斗，环佩光陆离。","有凤衔瑞图，雍雍鸣阶墀。","九苞花下舞，婆娑睹羽仪。","乘春歌燕喜，既翕和埙篪。","愿母寿九如，千秋以为期。"]},{"t":"赠黄启元孝感","f":"五言古诗","c":["黄生挺南国，耿耿慕前修。","孝恭夙所禀，朝夕何绸缪。","有母困床褥，吁天怀百忧。","刲股亟进之，而母疾以瘳。","刀圭信自取，负米岂其俦。","黄生吾小友，嘤鸣雅相求。","眷兹无双名，江夏良可侔。","愿生长努力，寿母及千秋。"]},{"t":"读姚新宁苦竹记有感赋此为赠","f":"五言古诗","c":["我生何不辰，苦作乱离人。","感君词更苦，读罢重酸辛。","城池初搆难，衣冠尽涂炭。","四顾纷戈矛，仓皇何所窜。","君自越危城，无人问死生。","形骸半摧折，豺虎复纵横。","僵卧坑堑底，自分必死矣。","全生仗素交，急难故如此。","万死始归来，妻子一悲哀。","旋复经刀锯，洒血遍蒿莱。","残生空落魄，世路黄金薄。","亲知反覆间，谁能重然诺。","天意不可知，骨肉重相随。","患难流离际，岂非玉汝时。","神物不终弃，青云看立致。","领牧到海涯，治行称独异。","倭兵纵烽烟，士卒困戈鋋。","临危一转战，孤城赖以全。","君本名卿后，才名称八斗。","何事数偏奇，所遇辄不偶。","騄駬下盐车，驰骋果谁如。","大鹏嗤斥鴳，天地鼓翼初。","逢君话夙昔，悲喜动颜色。","感激为斯词，词尽心脉脉。"]},{"t":"游栖霞寺呈陈子野倪公甫","f":"五言古诗","c":["乘兴恣幽寻，灵山郁苍翠。","飞泉树杪悬，危石云中坠。","策杖披荆蓁，言访前朝寺。","香气接诸天，珠光散初地。","碑横乱草中，苍苔蚀其字。","吊古几徘徊，临风发长喟。","云松结遐思，泉石豁幽意。","吾道本岩阿，无劳嗟弃置。"]},{"t":"赠赵子明","f":"五言古诗","c":["宛丘有佳士，夙抱希世珍。","连城称赵璧，明月产西秦。","精光射长虹，呵护多鬼神。","奈何早不售，掩泣徒悲辛。","鱼目翻见赏，燕石混其真。","连城与明月，沉埋气未伸。","郁勃陈蔡间，至宝难终湮。","会当献天府，临朝设九宾。","君其重自爱，毋惭抱璞人。"]},{"t":"和黄全之山人哭郑叔晓佥宪之作","f":"五言古诗","c":["伊人倏云亡，涕泪沾胸臆。","不复赋登高，伊谁颂酒德。","霓旌邈何之，云车焉可即。","夙昔心所欢，黄生更悽恻。","中夜起徬徨，有求如弗得。","瘴海回悲风，枫林青且黑。","三复悼亡词，古道生颜色。"]},{"t":"贞烈篇为林烈妇作","f":"五言古诗","c":["我昔遭寇乱，孤城嗟复隍。","倭兵猛于虎，士女驱群羊。","皎皎林家妇，引袂裂衷肠。","玉颜分必死，尘土非我藏。","烈气填胸臆，捐佩水中心。","贼徒俱动魄，按剑赫相望。","阴精彻河汉，白日天苍凉。","人生驹过隙，含垢辱冠裳。","岂不柔绕指，化此百炼刚。","吁嗟柯氏女，风与江海长。","芙蓉照秋水，岁岁含幽芳。"]},{"t":"题棠泉图寿棠泉郑公","f":"五言古诗","c":["嘉树郁繁阴，玉泉流不舍。","中有栖迟人，抱瓮灌梧槚。","伊昔际明时，亦既五其马。","钟鼎岂不荣，所贵和者寡。","耆旧伟衣冠，文章超风雅。","介寿及春阳，花下进杯斝。","绮席露为浆，雕盘龙作鲊。","神游孤射山，道契襄城野。","荧荧南极星，永锡兹纯嘏。"]},{"t":"夏日集东山同方员外黄山人黄给谏郑观察作","f":"五言古诗","c":["火云蒸四野，局促将焉如。","折简劳相命，高会城东隅。","磊磊山中石，郁郁路傍榆。","悬崖暑气薄，况与同心俱。","竹下罗丰膳，万籁间吹竽。","长啸若凤鸾，馀音彻九衢。","翩翩二三子，旨酒足欢娱。","凉风吹我发，烦襟藉以舒。","鸣蝉集深林，倦鸟下前除。","今日不乐饮，含情欲谁须。","人生天地间，贤愚同一区。","笑彼车马客，磬折竟焉趋。","登高能赋者，临眺且踌躇。"]},{"t":"送陈尧勋之浙为其先宪副公乞铭姚太史","f":"五言古诗","c":["瑟瑟秋风候，问君何所之。","君行双泪下，生别非所悲。","忆昔趋庭训，谆谆礼与诗。","定省朝还夕，为乐长在兹。","一旦风木摧，哀哀见无期。","泪尽继以血，殷忧当告谁。","独有太史铭，可以不朽为。","怀刺走千里，间关岂所知。","鸿雁声嗷嗷，浮云东南驰。","白马萧萧鸣，且当从此辞。","我闻重恻恻，掩泣一相持。","槜李在何方，山川路逶迤。","明发担簦去，严霜途中逵。","伤哉孝子心，金石坚不移。","太史秉直笔，文章光陆离。","千载一知己，临风涕涟洏。","君负青云姿，显扬会有时。","行矣重自爱，莫忘倚门思。"]},{"t":"赠袁伯益","f":"古风","c":["天地犹橐籥，人民原野鹿。","叔季日以漓，浑沌日以凿。","常道希无为，见素抱其朴。","至人剖玄门，游心洞枢轴。","烹鲜悟綦理，江海王百谷。","好静民自正，簿书无留牍。","从容著作林，六艺芳润漱。","缅想古时人，雅志慕黄鹄。","况乃柴桑翁，物外标芳躅。","千载谁知音，独为伤沉陆。","负材当明时，聊以见夙昔。","下士复高风，三握劳一沐。","既赓菁莪章，亦唱阳春曲。","以兹气味薰，兰?同馨馥。","怀刺遥相投，喜被清风穆。","挥麈吐玄言，虚来实吾腹。","南山归旧庐，北阙乘华毂。","愿保千秋名，矫首扶桑旭。"]},{"t":"题黄惟雅汪波千顷图","f":"五言古诗","c":["大鹏徙南溟，扶摇九万里。","斥鴳抢榆枋，控地而已矣。","大小量固殊，谁能区别此。","黄生产建安，夙慕前贤轨。","汪波以名图，朝夕劳仰止。","伊昔汉运微，贤豪皆披靡。","登龙失李公，祭皋悲范子。","屈蠖且泥蟠，独羡汝南美。","黄生青云姿，胸中无棘枳。","卜筑芝城隈，深林避泥滓。","汗漫游其中，可以格吝鄙。","瑶琴蓄一张，诗篇规四始。","自甘介浊酒，何用问臧否。","泰山等秋毫，天地犹一指。","汪洋千顷波，后先同一揆。","嗟余偃蹇人，结交淡如水。","虽然日往还，安能窥底里。","取醉有青尊，逆旅忘蓬累。","叔度本畸人，公衡亦快士。","愿子重勉旃，鲲自北溟起。"]},{"t":"题南郭别业 其一","f":"五言古诗","c":["一气散鸿濛，万汇纷天壤。","局促辕下驹，无乃婴世网。","所以古达人，翛然濠濮想。","鱼鸟日相亲，林木耽苍莽。","子也乐郊居，白云缔幽赏。","昏日憺忘归，超然神自爽。","仰眺烟峦姿，俯聆溪濑响。","衡门足栖迟，无劳歌独往。"]},{"t":"题南郭别业 其二","f":"五言古诗","c":["步出南郭门，言向青溪曲。","初日散平芜，人烟隐修竹。","桑麻迷术阡，籓离转隈隩。","始至豁尘襟，长啸骋遐瞩。","葱茜郁阳阿，雾霭沉阴谷。","既采涧边芹，亦摘畦中蔌。","客至且命觞，夜阑更秉烛。","濠梁乐在兹，垂钓从所欲。"]},{"t":"题南郭别业 其三","f":"五言古诗","c":["朝市多尘嚣，山林洵寂寞。","独有逍遥人，郊墟好栖托。","凿池养文鳞，学圃艺灵药。","岂不习纷华，所向在寥廓。","临流听桔槔，抱影坐丛薄。","抚琴伤猗兰，草玄掩高阁。","泛泛狎凫鸥，冥冥慕鸿鹄。","高卧似隆中，明志甘淡泊。"]},{"t":"题南郭别业 其四","f":"五言古诗","c":["褰裳涉三山，泛驾骋九州。","秦皇与周穆，往事良悠悠。","伊人事卜筑，乃在青门陬。","寒泉瑩碧沼，丛篁间绿畴。","菰蒲覆深浅，鸂鷘信沉浮。","岂云甘离索，聊以供息游。","空潭潜赤鲤，巨壑壑苍虬。","愿展云中翼，蓬蒿安足留。"]},{"t":"咏史十首 其一 之推","f":"五言古诗","c":["绵上山何高，千盘临绛水。","有蛇伏其中，依依母与子。","岂无从龙功，贪天窃所耻。","悬书在宫门，山中呼不起。","烈火被林皋，象焚良以齿。","生岂薄君恩，所愿从母死。","峨峨山上祠，郁郁松与梓。","至今寒食时，行人伤遗垒。"]},{"t":"咏史十首 其二 季子","f":"五言律诗","c":["延陵有宝剑，解挂徐君墓。","但酬一片心，安知存与故。","让国追夷齐，千乘非所顾。","岂复问遗金，负薪嗟道路。"]},{"t":"咏史十首 其三 屈原","f":"五言古诗","c":["三闾不可作，九歌有遗编。","伊昔仕宗国，岂不炳几先。","青蝇一坠耳，明月亦弃捐。","离骚空缱绻，利口急相煎。","娥眉嫉众女，萧艾茂兰荃。","侘傺古如此，非今独怃然。"]},{"t":"咏史十首 其四 荆轲","f":"五言古诗","c":["秦皇吞六国，蚕食下山东。","燕丹求壮士，易水歌悲风。","慷慨入咸阳，积诚贯白虹。","千金怀匕首，督亢图易穷。","报秦计不就，倚柱气何雄。","智哉张子房，潜击秦沙中。","十日索不得，翊汉成大功。"]},{"t":"咏史十首 其五 韩信","f":"五言古诗","c":["楚汉方龙斗，雌雄未可知。","淮阴起屠钓，佐汉一定之。","垓下兵已破，龙准偃旌旗。","楚人威震主，云梦亟相随。","兔死走狗烹，鼎镬所不辞。","妇言赤三族，韩彭良足悲。","以此感壮士，贻笑屠中儿。","饥从漂母饭，千金报不移。"]},{"t":"咏史十首 其六 灌夫","f":"五言古诗","c":["长安豪杰窟，权贵势相移。","今朝武安客，昨日事魏其。","一请城南曲，嫌隙良在兹。","所嗟俱戚里，安用倾夺为。","将军善使酒，骂坐且为谁。","一朝论弃市，笑杀颍川儿。"]},{"t":"咏史十首 其七 龚胜","f":"五言古诗","c":["炎祚既云微，五侯起专政。","成都怀异心，敢窃太阿柄。","亦有金縢书，居摄附姬圣。","传玺胁后宫，新室朔改正。","乃徵龚大夫，大夫固称病。","印绶岂不荣，所耻事二姓。","草玄者何心，竟乃作符命。"]},{"t":"咏史十首 其八 武侯","f":"五言古诗","c":["孔明心佐汉，长啸出隆中。","三分方割据，虎视竞相雄。","运筹劳旦夕，岂不誓匪躬。","关张不可作，帷幄难为功。","五丈原头石，汉室已将终。","即今前后表，读罢泪无穷。"]},{"t":"咏史十首 其九 靖节","f":"古风","c":["栗里有高人，浮云无所累。","有酒但相招，陶然?一醉。","采菊坐东篱，慨然发长喟。","身世两悠悠，那得长相寄。","白日梦羲皇，千载一高视。","解带谢时人，风流此未坠。"]},{"t":"咏史十首 其十 祢衡","f":"五言古诗","c":["汉运昔云颓，烟云四塞起。","魏武奋鹰扬，群策皆披靡。","雄辨哉祢衡，猖狂无与比。","阿瞒非所论，馀子安足齿。","江夏褊心人，豪强甘杀死。","至今鹦鹉名，遗恨沧浪水。"]},{"t":"题戴氏风泽山房 其一","f":"五言律诗","c":["谁栽千树橘，况近百花庄。","何用愚名谷，只宜醉作乡。","行藏高卧稳，岁月著书长。","兴到来看竹，无劳枉报章。"]},{"t":"题戴氏风泽山房 其二","f":"五言律诗","c":["结屋松林下，终朝独闭关。","猖狂知浊酒，摇落对青山。","种树荷锄去，寻僧采药还。","眷兹招隐地，倘许数跻攀。"]},{"t":"七夕舟中","f":"五言律诗","c":["银汉迎仙佩，金飙动客舟。","江湖逢此夕，砧杵报新秋。","尘世伤萍梗，清宵看女牛。","班姬团扇赋，吟罢不胜愁。"]},{"t":"真州送林明府携家还乡 其一","f":"五言律诗","c":["故园何处是，闽海路漫漫。","儿女天涯泪，穷愁世路难。","新诗工谢朓，往事拙潘安。","一卧秋江上，鲈鱼满钓竿。"]},{"t":"真州送林明府携家还乡 其二","f":"五言律诗","c":["枫林摇落候，有客赋将归。","湖海十年梦，星霜两鬓稀。","田园存晚计，萝薜遂初衣。","回首云霄迥，天涯万事非。"]},{"t":"真州送林明府携家还乡 其三","f":"五言律诗","c":["携家寻旧隐，岂为鹿门期。","客久薪如桂，愁来鬓有丝。","风尘悲荏苒，戎马苦驱驰。","归去盟猿鹤，岩居更不移。"]},{"t":"河上即事 其一","f":"五言律诗","c":["淮南飘泊者，秋水信轻舠。","萍梗还千里，风尘感二毛。","露滋葭菼冷，天阔雁鸿高。","蹈海吾何敢，来观八月涛。"]},{"t":"河上即事 其二","f":"五言律诗","c":["岂学庄生傲，聊为汗漫游。","衔杯捐万事，得句倚扁舟。","大汉秋风起，层城海气流。","长歌招隐赋，桂树暂淹留。"]},{"t":"河上即事 其三","f":"五言律诗","c":["秋色欺霜鬓，飘零胡不归。","沧洲吾道在，白眼世情非。","有客歌丛桂，何人问少微。","但看沙上鸟，来去总忘机。"]},{"t":"河上即事 其四","f":"五言律诗","c":["惨淡浮云色，萧条万里情。","风尘何落魄，湖海且逃名。","丧乱依刘表，离骚赋屈平。","陆沉无不可，归去问柴荆。"]},{"t":"河上即事 其五","f":"五言律诗","c":["浪迹缘何事，风帆任所之。","沧波含暝色，白露脆秋枝。","海市渔灯闹，江天雁影迟。","徘徊良夜月，赖有手中卮。"]},{"t":"河上即事 其六","f":"五言律诗","c":["偃蹇嗟吾道，支离笑此身。","何当归采菊，无日不思莼。","秋色丹枫冷，西风白发新。","翩翩鸿鹄气，千里去无垠。"]},{"t":"早春和方子及病中见示之作","f":"五言律诗","c":["汉京新改岁，怪尔避风尘。","伏枕原非病，裁诗最有神。","江山含紫气，梅柳斗青春。","憔悴还如昨，谁怜泽畔人。"]},{"t":"题九鲤湖仝郭士龙林翌甫作","f":"五言律诗","c":["琳宫高缥缈，登眺若飞翰。","地僻藤萝古，潭深日月寒。","石床空有藓，金灶已无丹。","采药从兹去，胡麻或可餐。"]},{"t":"寒食病起寄郑文蔚陈尧勋姚巽卿","f":"五言律诗","c":["落落天涯客，春风病未瘳。","此生扶药饵，故国梦松楸。","对雨逢寒食，经年拥敝裘。","王孙芳草路，何处不堪愁。"]},{"t":"金子鲁席上留别孤山社诸君","f":"五言律诗","c":["已结陶潜社，还看谢眺山。","一尊楼阁别，孤客海天宽。","金石心难变，江湖鬓已斑。","武陵良月夜，风雨未堪攀。"]},{"t":"赠屠纬真","f":"五言律诗","c":["何年辞建礼，天地老黄冠。","书著藏名岳，家贫服大丹。","西湖双桂棹，东海一渔竿。","回首长安日，浮云梦里看。"]},{"t":"咏谢娼蝶裙是贞吉王孙所贻","f":"五言律诗","c":["鲛鮹新出海，六幅制为裙。","拓得滕王蝶，妆成峡女云。","幽香春入梦，微步水生纹。","解咏空中雪，谢家自不群。"]},{"t":"闻林兆伦入九鲤诗以怀之","f":"五言律诗","c":["闻尔寻真去，何山第几重。","仙禽翔缥缈，大药采芙蓉。","梦醒寒潭水，心清晓月钟。","所嗟羁物役，徒想白云踪。"]},{"t":"送康孟担游吴越","f":"五言律诗","c":["芳草春晴候，看君赋远征。","岭云寒傍马，堤柳暗鸣莺。","酒湿鲛人泪，歌含郢客情。","相知劳问讯，白首卧柴荆。"]},{"t":"晚泊有怀","f":"五言律诗","c":["晚泊弋阳溪，孤舟望里迷。","桃花千树乱，杜宇数声啼。","积雨沉渔火，回风咽鼓鼙。","美人山水调，心折大江西。"]},{"t":"宛丘宿方子嗣宗馆中","f":"五言律诗","c":["久客辞梁苑，长途入宛丘。","故人一握手，千里散离愁。","秉烛寒砧夜，开尊片月秋。","翻思桃叶渡，系马醉青楼。"]},{"t":"汪司马招入桃源赏桂同吴翁晋苏君昭汪仲淹分赋得林字","f":"五言律诗","c":["桃源残暑退，城郭澹秋阴。","玉露分河汉，天香散桂林。","王孙招隐赋，公子采芳心。","偃蹇空山曲，攀援意转深。"]},{"t":"答王百谷","f":"五言律诗","c":["丛林寒夜别，明月寄新篇。","君自纫兰佩，余仍拍酒船。","百年贫傲世，半偈老逃禅。","欲下高斋榻，莺花二月天。"]},{"t":"题林邦介溪上别业","f":"五言律诗","c":["一水抱村流，门临杜若洲。","桃花停上骑，莲叶命扁舟。","波荡千峰影，风回六月秋。","西园名邺下，词赋重应刘。"]},{"t":"赋得紫阳洞","f":"五言律诗","c":["石洞俯崔嵬，龙蛇绣碧苔。","五丁何日凿，二酉此中开。","度索花仍发，浮丘鹤不回。","胡麻如可饭，长啸入天台。"]},{"t":"读黄亨夫万玉山房稿赋赠","f":"五言律诗","c":["曾谏长杨猎，翻为泽畔吟。","幽兰搴作佩，流水咽鸣琴。","天地飞扬态，山林偃蹇心。","若非同调者，白雪几知音。"]},{"t":"晋安馆中纪怀十首 其一","f":"五言律诗","c":["片帆初度峡，一上钓龙台。","睥睨三山出，辘轳万井开。","披襟下白鸟，散发步苍苔。","稍喜风尘静，谁当保障才。"]},{"t":"晋安馆中纪怀十首 其二","f":"五言律诗","c":["落魄馀双鬓，城隅问故人。","庭阴蕉叶老，秋色菊花新。","陋巷嗟何事，浮云笑此身。","床头多绿酒，莫厌客来频。"]},{"t":"晋安馆中纪怀十首 其三","f":"五言律诗","c":["秋色正摇落，山山柿叶黄。","那堪当逆旅，况复是重阳。","猿断沧江月，鸦啼老树霜。","不知孤馆客，何处泣干将。"]},{"t":"晋安馆中纪怀十首 其四","f":"五言律诗","c":["节序逢青女，他乡未授衣。","颜容愁里改，形影梦中归。","此日徒餐菊，何山可采薇。","却怜同病者，迢递暮云飞。"]},{"t":"晋安馆中纪怀十首 其五","f":"五言律诗","c":["青霜沾夜草，对此暗销魂。","短榻寒秋水，孤灯掩荜门。","途穷营桂玉，泪尽隘乾坤。","安得冥寥子，论心酒一樽。"]},{"t":"晋安馆中纪怀十首 其六","f":"五言律诗","c":["西风吹万籁，城郭起秋涛。","病色依双树，愁心感二毛。","香生黄菊细，寒傍白云高。","归去衡门下，凭谁读离骚。"]},{"t":"晋安馆中纪怀十首 其七","f":"五言律诗","c":["落叶纷如雨，愁人独倚楼。","千峰明远水，一鸟下沧洲。","湖海频相望，神仙未可求。","欲歌招隐句，乘月弄扁舟。"]},{"t":"晋安馆中纪怀十首 其八","f":"五言律诗","c":["越王台上望，秋色最堪怜。","五虎罗青嶂，双鸿破碧天。","芙蓉充杂佩，蟋蟀伴孤眠。","欲觅知音者，雷阳路几千。"]},{"t":"晋安馆中纪怀十首 其九","f":"五言律诗","c":["垂老长为客，愁心夜雨多。","绨袍谁复恋，白石自长歌。","薜荔侵荒径，梧桐冷碧柯。","披衣待明发，归思满烟萝。"]},{"t":"晋安馆中纪怀十首 其十","f":"五言律诗","c":["长铗歌鱼日，萧萧两鬓斑。","行云空入梦，倦鸟自知还。","汉浦怀仙佩，菱花对玉颜。","不知秋色里，几度望三山。"]},{"t":"赠金子鲁开府 其一","f":"五言律诗","c":["大楚劳分镇，全闽重策勋。","虎符娴妙略，龙剑静妖氛。","白羽摇山月，朱旗拂海云。","辕门无别事，传檄草雄文。"]},{"t":"赠金子鲁开府 其二","f":"五言律诗","c":["牙帐开青甸，鸾旗下绛霄。","星屯平野戍，月涌大江潮。","竹箭千章合，桃花万骑骄。","治书铃阁暇，清问到渔樵。"]},{"t":"秋夜同陈子卿集黄尧衢宅观菊","f":"五言律诗","c":["玉树风初冷，萧然白发新。","忽投江夏宅，又得杜陵人。","纫佩怀湘女，飧英笑楚臣。","何嫌欢秉烛，斗酒夜相亲。"]},{"t":"春日康孟担过访薜荔园","f":"五言律诗","c":["一径春阴里，松萝白日昏。","若非高士驾，谁到故侯门。","竹下诗偏秀，垆头酒未浑。","莫言供给少，枕藉有芳荪。"]},{"t":"集郑文蔚草堂同尚晋拱元作","f":"五言律诗","c":["秋色回丛桂，开尊咏楚骚。","青云谁附骥，白眼一持螯。","露冷花阴月，风生树杪涛。","子真栖谷口，何处弋鸿毛。"]},{"t":"登滕王阁","f":"五言律诗","c":["高阁秋逾迥，寒潭影自深。","君王不可见，过客一登临。","车骑风烟散，笙歌栋宇沉。","捲帘看暮雨，依旧洒城阴。"]},{"t":"秋日燕子矶即事","f":"五言律诗","c":["燕子枕江流，随波上下浮。","天分吴楚堑，地控帝王州。","网罟渔人集，帆樯估客愁。","白云尊酒尽，一啸秣陵秋。"]},{"t":"寄屠田叔","f":"五言律诗","c":["芳春已二月，偃蹇一狂夫。","风雨花开落，关山雁有无。","清言怀玉屑，傲吏对冰壶。","欲买扁舟去，蓬蒿病未苏。"]},{"t":"仝郑文蔚饮水亭作","f":"五言律诗","c":["水曲花偏丽，柴门客到稀。","藤萝盟不负，鸥鹭浴相依。","半醉眠芳草，长吟望翠微。","柳条春欲暮，肯令赏心违。"]},{"t":"秋夜仝吴湛之陈汝鉴过康孟担草堂","f":"五言律诗","c":["汗漫浑无事，杖藜向尔投。","幽兰纷薄暮，南斗耿清秋。","秉烛窥玄草，倾壶醉白头。","兴阑从去住，霜月夜悠悠。"]},{"t":"寄龙君善 其一","f":"五言律诗","c":["忽得燕中信，嗟君有谤书。","云霾丰狱剑，骥服太行车。","赤县飞腾久，青云拓落初。","桃花春水满，归混武陵渔。"]},{"t":"寄龙君善 其二","f":"五言律诗","c":["楚材岂易得，偃蹇一长叹。","遗爱歌南国，高名疾上官。","五都怀白璧，九畹艺幽兰。","且泛扁舟去，洞庭波浪宽。"]},{"t":"寄龙君善 其三","f":"五言律诗","c":["黄山与白岳，几度兴流连。","却笑缁衣客，翻憎贝锦篇。","帆樯归楚日，鸡犬避秦年。","若遇东来雁，裁诗寄綵笺。"]},{"t":"寄龙君善 其四","f":"五言律诗","c":["文章窥屈宋，仕路转堪悲。","去矣惊投杼，潸然泣染丝。","白云瞻故里，青桂喜连枝。","二酉探书罢，弹冠慰所知。"]},{"t":"游万山观仝郭次甫何长卿潘景升许去疾刘季然分得万字","f":"五言律诗","c":["策杖叩玄关，缘崖穿野蔓。","疑登黄鹤楼，更煮青精饭。","御气瞻朝元，临风听吹万。","眷兹汗漫游，岂负烟霞愿。"]},{"t":"水亭读凤皇山藏稿赠黄尧衢 其一","f":"五言律诗","c":["把酒临流日，读君卷里诗。","才华多幼妇，风雅是吾师。","龙种千群失，凤毛五色披。","凌云还有赋，况值好文时。"]},{"t":"水亭读凤皇山藏稿赠黄尧衢 其二","f":"五言律诗","c":["蓬门深谢客，隐几意何如。","偃蹇便科发，穷愁懒著书。","松阴移短榻，鸟迹乱前除。","幽独春相媚，无劳叹索居。"]},{"t":"水亭读凤皇山藏稿赠黄尧衢 其三","f":"五言律诗","c":["刘伶深嗜酒，陆羽解烹茶。","高士名犹在，吾生兴不赊。","负薪吟野径，煮石待山家。","若问浮生事，池塘暗落花。"]},{"t":"立秋日詹淑正见过小酌","f":"五言律诗","c":["寂寞掩柴荆，相过见汝情。","伏天流大火，片雨下孤城。","饥馑苏何日，江湖混此生。","垆头聊共醉，坐听井梧声。"]},{"t":"殷公觐招集水西亭仝何行吉詹淑正管象吉洪仲昭杨承之作","f":"五言律诗","c":["郭外生秋色，移尊集水西。","青山悬睥睨，白马驻招提。","丛桂淮南隐，芙蓉邺下题。","酣歌犹未已，归路夕阳低。"]},{"t":"寄题龙华寺兼柬堪公","f":"五言律诗","c":["宝幢山下寺，塔影挂层霞。","八水分功德，诸天散雨花。","将诗来入社，得酒便为家。","悟得无生理，超然转法华。"]},{"t":"缑溪馆中晤王永叔沈生余二明府","f":"五言律诗","c":["邮亭开锦帐，尊酒话襟期。","已下王乔舄，还吟沈约诗。","烽烟生海上，鸿雁隔天涯。","把袂休辞醉，重逢定几时。"]},{"t":"仙溪舟中报黄德符","f":"五言律诗","c":["为访仙源去，兰桡趁晚风。","山青烟树外，溪碧火云中。","胜事怀河朔，幽心寄桂丛。","美人渺何许，临水送飞鸿。"]},{"t":"周元孚邀仝邬汝翼胡应之何长卿黄白仲沈孺林登瓦官寺青莲阁作","f":"五言律诗","c":["瓦官名不减，高阁复青莲。","问法凭支遁，裁诗想谪仙。","黄图留王气，白浪落人烟。","宿障除烦恼，皈依不二禅。"]},{"t":"同彭玉润游摄山 其一","f":"五言律诗","c":["歇马行松径，寻僧度石桥。","欲窥龙藏胜，不惮虎溪遥。","踰岭参干佛，看碑辨六朝。","谁言陶处士，犹待远公招。"]},{"t":"同彭玉润游摄山 其二","f":"五言律诗","c":["一片烟萝地，空山涌白莲。","欲除烦恼障，先辨辟支禅。","鸟下翻经石，龙沉洗钵泉。","新诗携谢眺，翘首问青天。"]},{"t":"登谷城山","f":"五言律诗","c":["春入江山丽，登高醉眼开。","鹤盘沧海下，人蹑白云来。","解带悬修竹，飞觞藉落梅。","漫留金石句，天地妒雄才。"]},{"t":"秋日集欧桢伯青溪馆分得溪字","f":"五言律诗","c":["官舍清于水，开尊对木犀。","地当留笛步，客到浣花溪。","爽气乘秋入，斜阳度鸟低。","尚书期不顾，肯惜醉如泥。"]},{"t":"陈翰卿招集乌山同许伯纶康孟担杨任道作","f":"五言律诗","c":["卜筑南山下，开尊醉薜萝。","兰投湘女佩，雪和郢人歌。","海岳窗中尽，楼台树杪多。","翛然发长啸，挥手乱星河。"]},{"t":"春日雨中怀陈士传","f":"五言律诗","c":["律转青阳候，愁听曙雨声。","梅花寒自落，柳色嫩初生。","扑竹惊栖鹤，穿林却啭莺。","青山招隐处，延眺独含情。"]},{"t":"春日宿康孟担斋头赋赠","f":"五言律诗","c":["爱尔栖迟处，门庭静不哗。","春生书带草，香染木犀花。","短榻工文藻，晴窗阅岁华。","相过偏信宿，有酒不须赊。"]},{"t":"郊居即事","f":"五言律诗","c":["柴门流水曲，隐几绝逢迎。","乱竹烟初敛，孤村雨乍晴。","邻翁分药草，稚子进藜羹。","谁识幽居处，无营度此生。"]},{"t":"寄费无学","f":"五言律诗","c":["仙才不可见，大雅属斯人。","斗酒歌相劳，绨袍意独真。","文章穷屈宋，钟鼎辨周秦。","别尔匡庐去，千山若比邻。"]},{"t":"送立雨叔之海陵","f":"五言律诗","c":["三尺芙蓉佩，腰间色陆离。","那堪千里别，况复九秋时。","瓜步乘潮兴，芜城吊古诗。","小山丛桂好，莫忘倚门期。"]},{"t":"海上述怀","f":"五言律诗","c":["空门无剥啄，伏枕过今朝。","病色怀飧菊，生涯寄纬萧。","月摇湘女佩，风动颍人瓢。","寂寞玄经在，冥鸿未可招。"]},{"t":"送方伯书游北雍","f":"五言律诗","c":["长安多结侠，君去意何如。","黍谷春吹律，聊城客射书。","如云瞻璧水，有赋奏公车。","燕市逢人问，穷愁两鬓疏。"]},{"t":"度新岭作","f":"五言律诗","c":["二月且逢闰，披裘犹自寒。","阴云霾晓日，流水咽高滩。","马首风尘苦，羊肠道路难。","青山花渐发，不似故园看。"]},{"t":"京口早发","f":"五言律诗","c":["远寺疏钟动，长江片月流。","客愁眠不得，起视水边楼。","河汉星将曙，关门柝未休。","榜人初击楫，西上秣陵州。"]},{"t":"茶洋舟中","f":"五言律诗","c":["溪烟飞漠漠，久客荡归舟。","水落滩声急，天寒曙色浮。","风尘孤剑暗，戎马十年愁。","翻怪乡园近，伤心是旧游。"]},{"t":"对月有怀","f":"五言律诗","c":["爱此清秋月，盈盈水一方。","青天如挂镜，白露已沾裳。","波泛蟾宫冷，风飘桂阙香。","沉吟团扇句，能不断人肠。"]},{"t":"送吴公挺之建州","f":"五言律诗","c":["君向芝城去，云山望几重。","滩声喧黯淡，秋色冷芙蓉。","千里怀中剑，扁舟梦里钟。","溪头明月好，载酒幔亭峰。"]},{"t":"鄱阳舟中","f":"五言律诗","c":["乘槎千里客，一叶下鄱阳。","雁起闽天迥，烟连楚水长。","江鱼投网罟，海燕逐帆樯。","暮雨潇潇急，鸣桡欲断肠。"]},{"t":"左蠡雨泊怀彭使君","f":"五言律诗","c":["雨中停桂棹，一眺尽重湖。","巨浸吞吴楚，长鲸伏有无。","临渊嗟结网，见猎动飞弧。","何限怀人意，风波咫尺孤。"]},{"t":"雨中柬郑道行","f":"五言律诗","c":["二月雨声寒，萧条拥鹖冠。","疏钟沉别院，独鸟下空坛。","久客嗟燃桂，深山想采兰。","君家书带草，何似故园看。"]},{"t":"赋得金沙水同袁履善作","f":"五言律诗","c":["一派分阿耨，寒潭九里沙。","云蒸灵液煖，日动浏纹斜。","丽水盘初地，恒河露觉花。","欲将龙井去，支鼎试新茶。"]},{"t":"槜李雪中怀吴翁晋","f":"五言律诗","c":["积雪连平野，饥鸦不可闻。","相如怀授简，小令欲书裙。","水与银河接，山从玉垒分。","郢人歌寂寞，此际重思君。"]},{"t":"李节之招饮龙潭仝周希安宋初阳蔡幼公章子敬作","f":"五言律诗","c":["别馆临流迥，高楼背阁偏。","披云星作客，傲世酒称仙。","孤塔空中起，千家镜里悬。","何时乘夜雪，重泛剡溪船。"]},{"t":"夏日仝柯大启林晋伯郑若东柯尔珍避暑觉上人兰若","f":"五言律诗","c":["曳杖遵南国，言寻白社期。","龙应沉法水，鸟已集禅枝。","移席临溪阁，行厨荐露葵。","远公偏许饮，欲去漫攒眉。"]},{"t":"丁丑秋日书事","f":"五言律诗","c":["端拱劳清问，谁当万里城。","戎威骄假道，汉将大徵兵。","抗疏多新进，运筹属老成。","禁中频拊髀，颇牧昔时名。"]},{"t":"秋怀 其一","f":"五言律诗","c":["迢递千山道，疏林落日低。","传书悲塞雁，伏枕听莎鸡。","双鬓凋风雨，孤城厌鼓鼙。","东闽何处是，人在楚云西。"]},{"t":"秋怀 其二","f":"五言律诗","c":["西风摇落候，客自滞江城。","鸿雁三秋泪，蒹葭一水情。","醒逢渔父问，侠藉酒人名。","多病销皮骨，熊经学养生。"]},{"t":"送丘明华之浙中谒胡参政","f":"五言律诗","c":["朔气拥江门，离心那可论。","数声寒度雁，双泪暗啼猿。","访古严滩下，探奇禹穴存。","薇垣知国士，去矣漫销魂。"]},{"t":"寄余思澄","f":"五言律诗","c":["斗酒一为别，江湖叹索居。","诗曾题五柳，梦每拆双鱼。","彩笔风云丽，青山岁月虚。","交情深缱绻，争奈雁来疏。"]},{"t":"秋夜呈伯华","f":"五言律诗","c":["独坐高楼夜，萧然旅思生。","井桐秋一叶，城柝月三更。","剑合雌雄气，诗传鲍谢名。","山中丛桂在，无日不含情。"]},{"t":"泊金沙","f":"五言律诗","c":["西风吹瞑色，野雁倚孤舟。","水气将秋冷，溪声带月流。","交游虚顾盼，著作老穷愁。","明发扬帆去，隋珠何处投。"]},{"t":"木兰陂春泛同尧勋子韩文蔚作","f":"五言律诗","c":["春流绿于染，载酒罄交欢。","沙鸟轻相狎，江花笑未残。","衣含波影动，曲度柳条寒。","旷达真吾事，悠然咏考槃。"]},{"t":"病后伯华仁甫汝存携酒见访 其一","f":"五言律诗","c":["茂陵多病渴，萧瑟更悲秋。","忽载花间酒，同为月下游。","露华清欲滴，枫叶老堪愁。","莫惜如泥醉，风尘易白头。"]},{"t":"病后伯华仁甫汝存携酒见访 其二","f":"五言律诗","c":["偃蹇长为客，年华伏枕过。","贫应甘季次，病岂示维摩。","玉勒停秋草，金卮泛夕波。","徘徊情不浅，取醉月中歌。"]},{"t":"寄方景武二首 其一","f":"五言律诗","c":["塞上悲歌者，相违路几千。","著书曾入赵，击筑更游燕。","白羽徵兵日，黄金结客年。","幕中工草檄，还忆旧青毡。"]},{"t":"寄方景武二首 其二 题林敷毅立壶图","f":"五言律诗","c":["孤鹫界苍烟，凭高思渺然。","飞云迷古刹，落日俯平田。","醉拾金光草，閒寻玉乳泉。","天风吹短袂，缥缈若飞仙。"]},{"t":"见二毛作","f":"五言律诗","c":["生事惟高枕，萧然已二毛。","山中歌扣角，花下醉持螯。","身世穷何碍，风尘梦亦劳。","但教无俗事，随意读离骚。"]},{"t":"对月吟","f":"五言律诗","c":["凉风吹海月，皎皎度遥岑。","映水金波静，穿林玉树阴。","关山征妇泪，萍梗故人心。","独坐愁无赖，萧然动客吟。"]},{"t":"冬夜尧勋过访值雷雨大作","f":"五言律诗","c":["岁寒风雨夜，兴似剡溪船。","雷震嘉平月，星缠己夘年。","酒人吾独老，词客尔堪怜。","剪烛弹棋罢，联床一醉眠。"]},{"t":"初夏柬姚明府","f":"五言律诗","c":["群木散繁阴，怀人思不禁。","九华青似黛，几度梦相寻。","康乐题春草，步兵笑竹林。","溪头新水至，迟尔一披襟。"]},{"t":"怀晋安诸子 其一","f":"五言律诗","c":["忽忽惊残腊，萧条已二毛。","自应怀短铗，谁复恋绨袍。","夜雪深蓬径，寒松泻海涛。","不知词赋客，何处醉持螯。"]},{"t":"怀晋安诸子 其二","f":"五言律诗","c":["抱病衡门下，孤村岁暮时。","贫耽元亮酒，老爱建安诗。","雨雪龙蛇卧，稻梁鸟雀悲。","无诸二三子，几度梦中期。"]},{"t":"咏怀呈诸同社 其一","f":"五言律诗","c":["青鬓衡门下，朝来雪数茎。","文章嘲薄俗，贫病寄浮生。","樗栎元无用，藤萝合有盟。","中原二三子，鞭弭气纵横。"]},{"t":"咏怀呈诸同社 其二","f":"五言律诗","c":["吾道穷何甚，年丰亦苦饥。","江湖交渐薄，蒲柳病相依。","鹿破隍中梦，鸥忘海上机。","此生沉浊酒，荷锸未全非。"]},{"t":"咏怀呈诸同社 其三","f":"五言律诗","c":["夙昔飞扬态，年华去不留。","七星空佩剑，五月尚披裘。","翰墨非长技，稻粱那自谋。","江潭天地意，枯槁未应愁。"]},{"t":"咏怀呈诸同社 其四","f":"五言律诗","c":["草玄甘寂寞，谁识子云心。","十口穷相傍，二毛病不禁。","风尘空落魄，山水几知音。","万古江河色，滔滔岂陆沉。"]},{"t":"咏怀呈诸同社 其五","f":"五言律诗","c":["伏枕朝慵起，蓬蒿一径存。","妻孥亲井臼，裘葛失寒温。","药自频增减，诗多废讨论。","幸无车马迹，终日闭柴门。"]},{"t":"咏怀呈诸同社 其六","f":"五言律诗","c":["咄咄书空日，明时一病夫。","岁华徂薜荔，生事老江湖。","兴剧还看竹，心冥似据梧。","向来羁五斗，空自辱泥涂。"]},{"t":"仝赵献武林洁甫饮仲仁宅","f":"五言律诗","c":["谁道元龙傲，相逢意转亲。","但教千日醉，莫笑百年贫。","风雨能留客，烟花不负人。","夜来占太史，星已聚荀陈。"]},{"t":"戊子夏日祝士会招集信州北楼仝祝士南汪季美次唐人李郢韵","f":"五言律诗","c":["登楼愁作赋，把酒喜看山。","双鸟窥人下，孤云度陇还。","凶荒何日定，贫病此生閒。","醉里行吟客，悠悠恋故关。"]},{"t":"雨后怀陈尧勋","f":"五言律诗","c":["空斋听雨夜，芳树转秋声。","拥褐饶寒色，谈诗忆友生。","扁舟湖海兴，斗酒薜萝情。","那得狂相傍，长歌对月明。"]},{"t":"雨中写闷","f":"五言律诗","c":["漠漠黄梅雨，芝城五月秋。","湿薪吹不起，平础涨堪愁。","岁俭惊千里，家贫梦一丘。","谁能鞭日驭，长笑弄扁舟。"]},{"t":"旅病","f":"五言律诗","c":["焚香聊晏坐，旅食计萧然。","不分薪如桂，更嗟屋似船。","愁来脂髓尽，老至雪霜偏。","身世已如此，无劳问九天。"]},{"t":"病后柬陈季迪","f":"五言律诗","c":["白发长为客，孤灯暗抱疴。","据床亲药裹，伏枕想渔蓑。","生计浮云薄，乡心积雨多。","明朝逢竞渡，无奈独醒何。"]},{"t":"午日谢性卿招集斋中薄暮登楼赋此","f":"五言律诗","c":["竞渡逢佳节，多君折简招。","艾符方在户，莆酒且盈瓢。","对榻挥玄麈，登楼拂斗杓。","左徒遗恨在，千载未能消。"]},{"t":"坐雨柬吴师文","f":"五言律诗","c":["一榻嗟容膝，其如雨不堪。","人多愁桂玉，天岂漏东南。","逆旅怜同病，余生抱独惭。","囊中阿堵物，沽酒向谁酣。"]},{"t":"苦雨柬魏伯建","f":"五言律诗","c":["连朝依枕簟，积雨几时乾。","榴火枝头暗，茶烟竹里寒。","尊生甘社栎，佞佛礼旃檀。","为问参同子，何时振羽翰。"]},{"t":"雨中不得过季迪却寄","f":"五言律诗","c":["昨日花间酌，高谈碣石宫。","今朝云卧处，徒自叹飘蓬。","投辖情何限，操瓢兴不穷。","所嗟风雨恶，一水渺丝桐。"]},{"t":"题栟榈寺","f":"五言律诗","c":["礼佛寻龙藏，逢僧入虎溪。","诸天空色相，双树是菩提。","拂麈花初散，摊经日未西。","白莲堪结社，临去独留题。"]},{"t":"武彝逢钟明府","f":"五言律诗","c":["仙子栖真处，烟霞别有天。","金芝悬五岳，玉牒祝千年。","叶县窥丹灶，桃源泛钓船。","风流归茂宰，紫气望翩翩。"]},{"t":"武霞纪游 其一","f":"五言律诗","c":["鼓枻逢渔火，披衣混鹿群。","松含千嶂雨，草乱一溪云。","茅狗从天下，金鸡隔水闻。","幔亭张乐处，欲叩武夷君。"]},{"t":"武霞纪游 其二","f":"五言律诗","c":["长啸窥丹壑，寻幽入翠微。","风停鸾鹤驾，露湿薜萝衣。","谢豹穿林去，桃花夹岸飞。","闲来寻钓艇，不待乞渔矶。"]},{"t":"武霞纪游 其三","f":"五言律诗","c":["朅来停杖屦，访道上清宫。","翠落空潭水，涛生万壑风。","芝苓罗斗口，鸡犬驻云中。","即此堪招隐，何须问八公。"]},{"t":"武霞纪游 其四","f":"五言律诗","c":["黄冠偏爱客，载酒泛青溪。","春暖花争发，云深鸟自啼。","芝童调石髓，玉女进刀圭。","兴剧贪杯斝，挥戈日未西。"]},{"t":"武霞纪游 其五","f":"五言律诗","c":["铁笛吹何处，临风促落梅。","虹桥人不见，华表鹤初回。","九转留仙蜕，千秋辨劫灰。","当年刘阮辈，曾否到天台。"]},{"t":"武霞纪游 其六","f":"五言律诗","c":["缑山长跨鹤，叶县亦飞凫。","欲采三珠树，还藏五岳图。","乾鱼传汉峙，小犬吠仙都。","试问避秦者，于今尚有无。"]},{"t":"武霞纪游 其七","f":"五言律诗","c":["高阁延清眺，千崖气渺茫。","钟声沉断壑，鸟影曳斜阳。","倚竹风生籁，听泉月到床。","胡麻如可饭，未许问沧桑。"]},{"t":"武霞纪游 其八","f":"五言律诗","c":["斋心探道箓，细听步虚声。","不辨游三岛，焉知驻五城。","忽悬鲛室泪，翻忆鹿门耕。","何处安期枣，如瓜饷此生。"]},{"t":"仙门洞次苏大禹参君韵","f":"五言律诗","c":["共有寻真兴，林峦望里微。","朝乘青雀舫，暮叩白云扉。","涧水寒侵榻，岩花香扑衣。","僧来分乞食，信宿欲忘归。"]},{"t":"咏扇","f":"五言律诗","c":["汉宫纨扇动，人斗绮罗春。","素手披云叶，青娥媚月轮。","合欢将锦字，度曲绕梁尘。","莫作班姬怨，翩翩咏洛神。"]},{"t":"夏日对酒","f":"古风","c":["地僻便科发，一杯绿可亲。","竹林元我辈，河朔更何人。","却暑挥团扇，迎风岸角巾。","陶然?酩酊，莫是葛天民。"]},{"t":"冬日苦雨 其一","f":"五言律诗","c":["积雨愁无赖，蓬蒿日掩门。","炊烟沉北舍，饥鸟噪孤村。","南亩终何穫，东柯早已髡。","沉吟空自苦，抚景暗销魂。"]},{"t":"冬日苦雨 其二","f":"五言律诗","c":["檐前声不绝，枕上听来频。","乞米空怀帖，披裘那负薪。","形骸枯欲折，童仆馁生嗔。","如此萧条色，谁堪原宪贫。"]},{"t":"同施仲宣黄惟聚尧衢游九鲤湖分得齐字 其一","f":"五言律诗","c":["洞壑寻真去，扶筇过莒溪。","路随青嶂转，人与白云齐。","灌木寒风冷，閒猿隔水啼。","具茨何处是，七圣望中迷。"]},{"t":"同施仲宣黄惟聚尧衢游九鲤湖分得齐字 其二","f":"五言律诗","c":["托乘探仙箓，三花驻马蹄。","泉声喧万壑，云气护层梯。","采秀骑玄鹿，传书倩碧鸡。","霞浆堪一醉，扫石待留题。"]},{"t":"同施仲宣黄惟聚尧衢游九鲤湖分得齐字 其三","f":"五言律诗","c":["瞥见如泥髓，前身岂姓稽。","湖澄涵白练，山迥接青霓。","六博仙初聚，三珠鹤并栖。","水晶帘正捲，吾欲授刀圭。"]},{"t":"同施仲宣黄惟聚尧衢游九鲤湖分得齐字 其四","f":"五言律诗","c":["倚杖看飞瀑，空山日渐西。","云中思跨鲤，水底欲燃犀。","梦觉星初聚，诗成马正嘶。","避秦还此地，何日重攀跻。"]},{"t":"赠马聚生 其一","f":"五言律诗","c":["大楚雄风起，如云竹马迎。","地当闽斥卤，官即汉廷平。","荔子香侵阁，壶公翠入城。","花关人吏散，坐听鸟嘤嘤。"]},{"t":"赠马聚生 其二","f":"五言律诗","c":["皎皎冰壶月，郡斋乐事多。","衣沾萱草色，酒对棣华歌。","一雨苏粳稻，长松映薜萝。","谢公诗满卷，倘许和羊何。"]},{"t":"夏日题东麓草堂 其一","f":"五言律诗","c":["出郭乘青雀，看山坐水湄。","晴云笼碧树，好鸟啭高枝。","把酒荷香入，摊书竹影移。","硕人栖此地，长咏考槃诗。"]},{"t":"夏日题东麓草堂 其二","f":"古风","c":["池上凉风至，荔枝香满庭。","凌波双鹭白，捲幔数峰青。","绮丽追金谷，诙谐得岁星。","相将?一醉，身世等浮萍。"]},{"t":"夏日题东麓草堂 其三","f":"五言律诗","c":["青莲花乍吐，长啸一登台。","芳树摇青盖，轻霞动举杯。","骚人裁竹箨，浣女摘杨梅。","为问西园客，谁当绣虎才。"]},{"t":"夏日题东麓草堂 其四","f":"五言律诗","c":["地僻便科发，烟霞更可亲。","何来垂白者，得御草玄人。","舞蝶窥花幄，游丝绾钓纶。","溪山堪小隐，莫问武陵津。"]},{"t":"宿林观察园亭 其一","f":"五言律诗","c":["长歌招隐日，别业旧西耕。","花竹分三径，楼台拥五城。","云含秋雨色，树带海涛声。","把酒欢何极，重怜下榻情。"]},{"t":"宿林观察园亭 其二","f":"五言律诗","c":["郭外开精舍，篮舆恣往还。","虬龙潜巨壑，猿鹤啸空山。","凿井偏投辖，入林但闭关。","庭前饶玉树，倘许数追攀。"]},{"t":"三河舟中","f":"五言律诗","c":["漠漠千山雨，飘飘一叶舟。","东南饶瘴疠，身世任沉浮。","丧乱吟逾苦，风尘醉亦愁。","此心关去住，能不愧沙鸥。"]},{"t":"春日閒居 其一","f":"五言律诗","c":["浮海吾何敢，龙蛇深自藏。","九章怀屈宋，一榻傲羲皇。","老乏还丹诀，贫馀辟谷方。","试听渔父曲，吾道属沧浪。"]},{"t":"春日閒居 其二","f":"五言律诗","c":["艺苑云蒸日，邹枚尚典型。","登坛名跋扈，倾国色娉婷。","独笑桑间饿，谁怜泽畔吟。","朱弦千古调，无梦不湘灵。"]},{"t":"春日閒居 其三","f":"五言律诗","c":["削迹浑无事，为园抱瓮劳。","逢人聊应马，玩世漫持螯。","洞壑探蝌蚪，江天纵羽毛。","不知吴市卒，那用姓名逃。"]},{"t":"春日閒居 其四","f":"五言律诗","c":["高蹈非无意，疏慵合废居。","狂呼厨下酒，奇爱帐中书。","著述饶蓬鬓，行藏自草庐。","冥冥鸿鹄举，矰缴竟何如。"]},{"t":"集宗振宅","f":"五言律诗","c":["海上春将尽，开尊兴不孤。","青山寒击筑，黄鸟间呼卢。","岁月甘龙卧，纵横学狗屠。","风尘空荏苒，酒尽更须酤。"]},{"t":"麦斜岩别吴文仲比部","f":"五言律诗","c":["何事寻樵谷，空山路转微。","岳莲飞入座，岩桂扑行衣。","众壑趋云窦，孤峰对石扉。","徘徊珠树鹤，明发又分飞。"]},{"t":"冬夜徐茂吴集汪惟一邵长孺汪虞卿于建初寺分得青字","f":"五言律诗","c":["寒月照松棂，昙花香满庭。","偶来沧海客，一缀白榆星。","妙偈参诗入，微钟杂梵听。","危楼频徙倚，醉眼落空青。"]},{"t":"卧游室为图南题","f":"五言律诗","c":["不须穷亥步，一室足徜徉。","榻上逢宗炳，书中得子长。","骖云低五岳，吸露驻三光。","更有凌云梦，天孙赠锦裳。"]},{"t":"寄陈尧勋","f":"五言律诗","c":["十里江城路，怀人过五陵。","交情深尺牍，别梦醒孤灯。","我已歌衰凤，君还赋大鹏。","高楼秋月白，尊酒共谁登。"]},{"t":"夏日集普德寺竹林仝林光甫张子明马一卿赋 其一","f":"五言律诗","c":["习静投莲社，逃名醉竹林。","可怜千古事，独契一时心。","祗树巢幽鸟，繁云结夕阴。","风来醒客梦，溽暑岂相侵。"]},{"t":"夏日集普德寺竹林仝林光甫张子明马一卿赋 其二","f":"五言律诗","c":["趺坐对琅玕，空林夏亦寒。","清斋供野蔌，杂佩纫幽兰。","灌木鸣蝉静，孤村过雨残。","支公能爱客，不厌借蒲团。"]},{"t":"饮马于阶草堂仝钱叔达康孟担作","f":"五言律诗","c":["华筵开别墅，坐对菊花香。","自爱倾醽醁，何须典鹔鹴。","徵歌多子夜，纵酒得高阳。","秉烛忘归去，沉沉漏未央。"]},{"t":"康元龙招饮草堂分得心字","f":"五言律诗","c":["园林秋色淡，置酒傍花阴。","隔竹寒蝉静，高楼宿雾深。","图书清玉案，山水和瑶琴。","踏月听歌去，悠悠子夜心。"]},{"t":"鄱阳湖舟中","f":"五言律诗","c":["挂帆彭蠡泽，渺渺但乘风。","日月涵元气，匡庐插太空。","鸿多遵浅渚，龙自远幽宫。","何事䲭夷子，飘然类转蓬。"]},{"t":"海陵除夜仝德夫宗振道昭邦彦作","f":"五言律诗","c":["雨雪欺双鬓，天涯那可亲。","却怜今夜酒，俱是旧游人。","牛马怀他日，龙蛇蛰此晨。","新诗裁刻烛，读罢倍伤神。"]},{"t":"元日","f":"五言律诗","c":["逆旅逢元日，相看总隐沦。","愁来诗不废，客久鬓如新。","把钓怀东海，垂衣想北宸。","江湖浊酒在，一醉任吾真。"]},{"t":"空囊","f":"五言律诗","c":["芳草经春歇，阴云入夏多。","鹭鸥群水曲，猿狖啸岩阿。","白发何生理，青山且放歌。","空囊归未得，倚棹笑蹉跎。"]},{"t":"雨中书所见","f":"古风","c":["江村日日雨，四月尚衣绵。","?屋颓沙岸，麦丘尽水田。","深林喧宿鸟，远浦起寒烟。","何物禁愁得，杖头乏酒钱。"]},{"t":"至日","f":"五言律诗","c":["旅馆逢长至，萧萧雨雪时。","愁肠添一线，短发乱如丝。","天地阳初转，风尘泪欲垂。","此生驹隙过，但罄手中卮。"]},{"t":"过兰溪投赠胡元瑞兼柬王元美先生","f":"五言律诗","c":["十载交游冷，新从縠水过。","上书违北阙，讲道老西河。","病久青云薄，愁深白发多。","郢人今已矣，雪调向谁歌。"]},{"t":"九日仝陈别驾登白鹤峰","f":"五言律诗","c":["素节登高处，相看岂故乡。","乾坤同逆旅，岁月又重阳。","睥睨孤城暮，潺湲二水长。","归心浑欲折，篱畔菊初黄。"]},{"t":"岁暮怀归","f":"五言律诗","c":["天涯双鬓改，雨雪岁将徂。","自笑穷愁老，谁云去住孤。","诗篇销日月，酒态傲江湖。","何限还家梦，沧洲一钓徒。"]},{"t":"送李茂承之白下","f":"五言律诗","c":["任达云间彦，千秋一季鹰。","若非君落拓，谁与古凭陵。","桃叶春风艇，昙花夜月灯。","六朝多胜迹，幽兴日堪乘。"]},{"t":"雨中集洪仲昭楼居仝詹淑正何行吉管象吉殷公觐分得樽字","f":"五言律诗","c":["南楼云里迥，星斗若堪扪。","邀客秋初爽，看山日渐昏。","雨声寒几席，烛影乱金樽。","莫问城笳起，新诗坐夜论。"]},{"t":"登清水岩","f":"五言律诗","c":["鹫岭开云际，扶藜登眺初。","不知身历险，只觉气凌虚。","楼观空中尽，松萝象外疏。","陶然参绣佛，何物是真如。"]},{"t":"春日怀所知 其一","f":"五言律诗","c":["眼看春草色，忽动故园吟。","入社分僧供，临流听鸟音。","三洲沧海近，九漈白云深。","肠断离群者，徒劳梦里寻。"]},{"t":"春日怀所知 其二","f":"五言律诗","c":["一春多苦雨，落魄愿多违。","白雪生明镜，缁尘染素衣。","溪流清绕舍，竹影乱侵扉。","若问江湖兴，朝朝咏式微。"]},{"t":"度分水关","f":"五言律诗","c":["五载还乡客，嘤嘤鸟恋群。","往来人渐老，闽越水初分。","远树含烟瘴，诸天幻火云。","归心悬落日，处处乱蝉闻。"]},{"t":"赋得桐江水寄许才甫","f":"五言律诗","c":["碧绿桐江水，羊裘隐在兹。","滩声流日月，山色拥玻璃。","林莽供樵爨，烟波理钓丝。","君家欲洗耳，舍此更何之。"]},{"t":"午日泛舟怀古","f":"五言律诗","c":["载酒当佳节，临流感慨深。","笙歌喧远浦，烟雨散平林。","抱石千秋泪，怀沙午日心。","遗风留泽畔，落日想行吟。"]},{"t":"题君霖六书楼","f":"五言律诗","c":["公子开高阁，参差碧汉齐。","书应工倒薤，帙已映燃藜。","翼轸光堪摘，匡庐望不迷。","几人能载酒，时上白云梯。"]},{"t":"开元寺对月怀归","f":"五言律诗","c":["兰若春晴夜，横空片月新。","诸天澄素影，初地绝轻尘。","丧乱长为客，婵娟故恼人。","青山归去好，莫遣鬓如银。"]},{"t":"久不得子韩粤中消息怅然有怀","f":"五言律诗","c":["无赖炎州客，漂零胡不归。","天涯双鬓改，岭外尺书稀。","珠探鲛人室，帆遥燕子矶。","何时重握手，一醉典春衣。"]},{"t":"水晶宫有怀","f":"五言律诗","c":["白云随杖屦，閒到赤松家。","倚槛听流水，怀人怨落花。","游仙长枕石，避世饱餐霞。","未了浮生事，青门老种瓜。"]},{"t":"泊都昌","f":"五言律诗","c":["白发甘丘壑，胡为叹转蓬。","乍看西过雨，旋起北来风。","尺素思双鲤，扁舟涨片鸿。","囊中金已罄，那得醉新丰。"]},{"t":"谼中避暑仝郭次甫龙君善庄静甫汪仲淹潘景升刘季然分得侵字","f":"五言律诗","c":["仙源迷咫尺，暂卧白云深。","阁对悬崖静，庭分灌木阴。","松涛醒鹿梦，洞壑起龙吟。","纵饮追河朔，都忘暑气侵。"]},{"t":"集鼓山寺仝从甫郑尧邻吴道敬吴赞庭陈万里作","f":"五言律诗","c":["陶潜栖白社，谢眺赋青山。","地似藤萝外，人多伯仲间。","裁诗幽鸟下，移石暮云还。","但得如渑酒，沉冥学闭关。"]},{"t":"读射阳湖稿赠杨肖韩","f":"五言律诗","c":["四杰推杨炯，新诗郢调孤。","柳移彭泽县，花匝射阳湖。","丹灶开仙令，沧洲老钓徒。","骊龙衔片月，应识夜光珠。"]},{"t":"鹅湖馆中别詹修之 其一","f":"五言律诗","c":["余向江南去，君为蓟北行。","舟车含别泪，风雨恋交情。","燕市初求骏，湘累自采蘅。","天涯如见月，莫负岁寒盟。"]},{"t":"鹅湖馆中别詹修之 其二","f":"五言律诗","c":["一朝复一夕，身世似飘蓬。","雁度寒云外，莺啼细雨中。","形骸嗟我老，肝胆与君同。","岐路愁分手，劳歌思不穷。"]},{"t":"建安别诸祖守宪弟道佩","f":"五言律诗","c":["仝舟溯建水，岐路别如何。","旅鬓秋霜短，乡心夜雨多。","寒鸿依海岛，岩狖啸烟萝。","回首三江水，何时共钓蓑。"]},{"t":"寄赠吴体中明府","f":"五言律诗","c":["双凫飞赤县，才子重南金。","花吐临川笔，风清单父琴。","千峰澄碧水，片月照寒林。","未得参禅去，徒怀仰止心。"]},{"t":"黄贞甫读书灵隐寺禅楼赋赠","f":"五言律诗","c":["之子穷经处，高楼拱翠峦。","龙疑盘洞壑，凤欲啄琅玕。","星斗挥毫乱，烟霞拂枕寒。","支床鸡骨在，临别劝加餐。"]},{"t":"集林晋伯霞村别业","f":"五言律诗","c":["园林多秀色，载酒趁花朝。","听鸟凭江槛，看云度野桥。","曲池含月影，列嶂乱霞标。","乘兴还过此，无劳折简招。"]},{"t":"送林德夫之淮南","f":"五言律诗","c":["相逢秋已暮，又尔别夫君。","千里扬帆去，三山落叶纷。","吴陵迷夜雪，楚水隔寒云。","日夕歌丛桂，还招海上群。"]},{"t":"哭林翼甫","f":"五言律诗","c":["闻汝风流尽，青春重可哀。","江湖愁里隔，形影梦中回。","片玉埋秋草，孤琴掩夜台。","天涯交谊在，无计奠椒杯。"]},{"t":"访徐唯起绿玉斋喜陈伯孺僧如翰并至席上怀惟和","f":"五言律诗","c":["城隅开一径，曳杖到玄亭。","山色窗中出，秋声竹里听。","焚香参绣佛，解佩赠湘灵。","不尽怀人意，寒云隐翠屏。"]},{"t":"赠松溪昌明府","f":"五言律诗","c":["灌坛行雨令，千载复南州。","制锦花为县，鸣琴月满楼。","双溪分曲水，五柳繫仙舟。","我有湛卢兴，何时挟蒯缑。"]},{"t":"送金开府还武林 其一","f":"五言律诗","c":["匡时推建节，感事遂初衣。","威震彭湖外，功成越徼归。","风霜依豸府，烟雨恋渔矶。","身去名弥重，未应便息机。"]},{"t":"送金开府还武林 其二","f":"五言律诗","c":["八载纾南顾，重臣两鬓丝。","艰危满眼急，牢落寸心知。","雁度惊风冷，帆摇带雪迟。","五湖烟月好，长啸学鸱夷。"]},{"t":"送金开府还武林 其三","f":"五言律诗","c":["东南深保障，行止却踟躇。","羽檄今初定，军储更有馀。","自甘隐豹意，那问乐羊书。","父老并州泪，攀留拥后车。"]},{"t":"送金开府还武林 其四","f":"五言律诗","c":["孤山原结社，归去问吾曹。","苏小门前柳，蒋公径里蒿。","梦魂消策海，词赋盛观涛。","不浅山阴兴，愿追载酒舠。"]},{"t":"送金开府还武林 其五","f":"五言律诗","c":["心事明天日，才猷迈伯王。","暂抛鱼鸟阵，一卧水云乡。","葛井丹初熟，䅊侯泽正长。","安危须将相，元是郭汾阳。"]},{"t":"曹能始王玉生沈从先同入梅岩余蹑其后不及 其一","f":"五言律诗","c":["乘舟游汗漫，倚杖陟崔嵬。","晓濑千盘雨，春梯百丈苔。","餐霞元吏隐，采秀总仙才。","所愧非禽向，何缘共往来。"]},{"t":"曹能始王玉生沈从先同入梅岩余蹑其后不及 其二","f":"五言律诗","c":["谢客耽山水，梅生厌市廛。","桃源初问路，桂树不知年。","粱糗青泥缮，刀圭白日传。","如何乖羽翼，清夜梦相牵。"]},{"t":"八咏禁体 其一 夕阳楼","f":"五言律诗","c":["十二凌霄迥，雕甍驻晚晖。","层霞侵绣闼，返照逗朱扉。","倚槛群鸦集，巡檐乳燕飞。","晚妆羞独上，花月隔音徽。"]},{"t":"八咏禁体 其二 流黄月","f":"五言律诗","c":["少妇停梭处，银河玉镜飞。","蟾窥双镊影，兔射七襄机。","促织声偏急，合欢信转稀。","关山吹玉笛，何处是金微。"]},{"t":"八咏禁体 其三 芦花风","f":"五言律诗","c":["蘋末商飙动，飘飘舞絮狂。","行空疑泛梗，著树若飞霜。","衬水鱼争沫，披云雁作行。","所嗟人远戍，秋老未还乡。"]},{"t":"八咏禁体 其四 芭蕉雨","f":"五言律诗","c":["绮阁背园林，晴光满绿阴。","忽闻声淅沥，自觉气萧森。","远梦醒凉簟，清商咽素衾。","博山炉欲烬，欹枕听馀音。"]},{"t":"八咏禁体 其五 霜前叶","f":"五言律诗","c":["园林秋色淡，青女信先知。","憔悴自今日，葳蕤非故枝。","洞庭波欲起，金井露为期。","赋质元轻薄，托根终不移。"]},{"t":"八咏禁体 其六 松上雪","f":"五言律诗","c":["架壑材凌劲，孤标压六霙。","龙疑蟠玉垒，鹤自下青城。","气肃徂徕节，光浮琥珀精。","肯随桃李艳，惟结岁寒盟。"]},{"t":"八咏禁体 其七 画堂燕","f":"五言律诗","c":["甲第开王谢，双栖试羽裳。","空巢依藻棁，将子下雕梁。","尾剪差池影，泥含百和香。","谁堪荡子妇，刺绣掩空房。"]},{"t":"八咏禁体 其八 沙场雁","f":"五言律诗","c":["阴碛排云下，边庭唳月新。","稻粱怀汉苑，羽翼染沙尘。","避缴愁分猎，衔芦怯渡津。","青闺书不到，魂断玉关人。"]},{"t":"赵仁甫招饮芝园仝颜左史李茂才作","f":"五言律诗","c":["华亭临曲水，避暑更适宜。","日影松阴薄，蝉声阁外迟。","寻诗寻竹径，佐酒荐园葵。","池上凉风满，何妨倒接䍦。"]},{"t":"访汪仲嘉松明山中时有传余物化者相见愕然醉后宿肇林赋此","f":"五言律诗","c":["故人江左别，风雨十年多。","蒿里空垂泪，蓬门且放歌。","张灯如寤寐，把酒慰蹉跎。","托宿僧僚近，往来步屧过。"]},{"t":"过汪仲淹故居感怀喜见其子无央","f":"五言律诗","c":["一入千秋里，白榆感旧游。","何年埋玉树，此日邈丹丘。","花湿平芜雨，蝉鸣灌木秋。","不孤嵇绍在，腰下解吴钩。"]},{"t":"雨中柬陈鲁彦","f":"五言律诗","c":["空门何寂寂，积雨暗松枝。","抱病衣偏冷，安贫鸟亦饥。","看经先嗽齿，断酒不攒眉。","徙倚孤亭上，频吟伐木诗。"]},{"t":"雨中汪仲嘉惠米却谢以诗","f":"五言律诗","c":["双鬓愁中短，六时客里长。","何期三日雨，更惹九回肠。","谁授餐霞诀，空馀辟谷方。","故人分玉粒，听雨饱绳床。"]},{"t":"紫阳道中逢余珍甫","f":"五言律诗","c":["忆昔夷门别，风尘阅岁华。","君怀新甫柏，我种五侯瓜。","乍见惊蓬鬓，相携入酒家。","明朝分羽翼，依旧隔天涯。"]},{"t":"和汪司马寄题仙岩诗为云池上人作","f":"五言律诗","c":["青莲初架壑，胜地已声闻。","未得瞻花雨，徒然想法云。","幽愁归自在，究竟总无文。","所愿从师去，醍醐乞几分。"]},{"t":"赠胡广文","f":"五言律诗","c":["才名高海国，振铎向闽天。","桃李沾春雨，鱼龙破晓烟。","传经垂绛帐，对客坐青毡。","独有凌云气，时悬北斗边。"]},{"t":"秋日登钓台 其一","f":"五言律诗","c":["天涯秋乍转，重眺子陵台。","潭古鱼龙伏，山空鹳鹤来。","自耽丘壑老，那问伯王才。","所愧扁舟客，忘机鸟转猜。"]},{"t":"秋日登钓台 其二","f":"五言律诗","c":["七里终垂钓，高风薄九霄。","萧曹偏佐汉，巢许岂臣尧。","地僻连桑野，台狐控斗杓。","羊裘何处问，秋树正鸣蜩。"]},{"t":"秋日登钓台 其三","f":"五言律诗","c":["犯坐星为客，狂奴重此邦。","功虽希渭水，计自老湘江。","古洞无眠鹿，荒祠有吠厖。","临风听短笛，调入水云腔。"]},{"t":"秋日登钓台 其四","f":"五言律诗","c":["凭高一长啸，眼底尽飞潜。","齐国今非汉，渔人旧是严。","风号流水转，云散乱峰尖。","兴尽乘槎去，松梢吐玉蟾。"]},{"t":"槜李别张子明 其一","f":"五言律诗","c":["汗漫逢长水，愁心感岁华。","非关贫刺骨，那得远辞家。","双鬓经秋短，孤鸿带日斜。","露团芳草夕，何处咏蒹葭。"]},{"t":"槜李别张子明 其二","f":"五言律诗","c":["异地怜同病，君归不可留。","弟兄俱白首，风月正清秋。","失路悲寒雁，忘机愧野鸥。","一杯聊惜别，不为答吴钩。"]},{"t":"桐江舟中怀金中丞","f":"五言律诗","c":["鼓棹今何适，桐庐际晓行。","山多藏玉笈，水不染尘缨。","别洞龙眠稳，长空鹤唳清。","仙人云树里，犹似隔蓬瀛。"]},{"t":"赠章少府","f":"五言律诗","c":["豫章需上国，一命佐鸣琴。","舄借双凫影，庭分五柳阴。","贤劳推骥足，抚字见鸾心。","自是神仙尉，莺声啭上林。"]},{"t":"秋日同张子明王德载陶大冶访王上之留饮舟回作","f":"五言律诗","c":["共泛彪湖棹，言寻处士家。","鹿门归采药，龙井唤烹茶。","玉麈谈名理，青莲供法华。","溯洄秋色里，浥露咏蒹葭。"]},{"t":"送了义上人还普陀","f":"五言律诗","c":["云中开宝刹，碧海信浮槎。","一火空尘劫，诸天护法华。","随缘飞片锡，发愿礼三花。","从此皈依处，禅心定洛迦。"]},{"t":"陈元朋张绍和二孝廉夜集游宗振嘉树林即席分韵 其一","f":"五言律诗","c":["楚楚谈天客，归来自帝州。","讵堪逃竹所，未许老糟丘。","投辖星窥井，衔杯月满楼。","相逢欢卜夜，凉气飒疑秋。"]},{"t":"陈元朋张绍和二孝廉夜集游宗振嘉树林即席分韵 其二","f":"五言律诗","c":["二妙才名重，论交惬素心。","斗牛双入佩，山水独知音。","醉月穿萝径，乘风啸竹林。","图南绝跋扈，莫遣鬓萧森。"]},{"t":"夏日林晋伯邀蔡伯达明府避暑清溪同林元和钱叔达黄尧衢柯尔珍作","f":"五言律诗","c":["别墅清溪曲，宾筵但荐瓜。","舒荷风未绽，扶荔日初斜。","波泛空江月，香闻隔岸花。","留连还秉烛，盘谷欲移家。"]},{"t":"题隆甫小像","f":"五言律诗","c":["季鹰称任达，之子慕高风。","貌岂缘诗瘦，愁多入赋工。","云中惟附骥，海上自冥鸿。","色相无劳著，万缘悉已空。"]},{"t":"寿夏司马 其一","f":"五言律诗","c":["龚黄推上佐，曾识汉庭名。","北海春初煖，南山月正明。","家传金粟盛，官比玉壶清。","一自条风起，讴歌处处声。"]},{"t":"寿夏司马 其二","f":"五言律诗","c":["司马云台望，大夫雪苑才。","清风闻八郡，紫气近三台。","阁静鱼频挂，庭閒鹤正回。","此时瞻法象，应可拟蓬莱。"]},{"t":"寿夏司马 其三","f":"五言律诗","c":["圣朝崇展骥，仙籍重骖麟。","名在丹台旧，荣分海甸新。","占星知是岁，问俗想行春。","即此棠阴茂，还看饰羽轮。"]},{"t":"寿夏司马 其四","f":"五言律诗","c":["降岳传周典，偷桃忆汉官。","仙风应不减，吏道亦何难。","楼橹烽烟息，菁莪湛露团。","冈陵惭共祝，敢谓臭如兰。"]},{"t":"林太守元和招游凤林乐丘","f":"五言律诗","c":["相逢半隐逸，太守醉称翁。","中散情多放，荣期乐未穷。","溪毛蘋藻绿，山果荔枝红。","把酒听新瀑，长松日暮风。"]},{"t":"送张证性之粤","f":"五言律诗","c":["竹里啸清秋，怜君复远游。","丹已寻勾漏，药自采罗浮。","老骥怀千里，名山动四愁。","何时归故国，访我白蘋洲。"]},{"t":"赋得东山屐","f":"五言律诗","c":["谢公高卧日，江左卜安危。","偏纵登山屐，长吟在涧诗。","烟霞随缓步，松竹结幽期。","雅量谁能测，犹传折屐时。"]},{"t":"五月三日仝诸君泛舟 其一","f":"五言律诗","c":["南薰吹灌木，载酒命兰舟。","兴动沧浪水，香生杜若洲。","清言谐夙契，大块等浮沤。","俱罄杯中物，独醒空自愁。"]},{"t":"五月三日仝诸君泛舟 其二","f":"五言律诗","c":["海曲分南北，为欢驾彩虹。","三江澄碧浪，五月御薰风。","蒲酒渔郎醉，菱歌浣女工。","眷兹游汗漫，何必问新丰。"]},{"t":"纸帐","f":"五言律诗","c":["岂厌流苏艳，还将茧素裁。","连床堪染翰，捲幔欲妆梅。","匹练分云出，罗纹带月开。","个中人似玉，曾否梦阳台。"]},{"t":"挽孙司理 其一","f":"五言律诗","c":["岂厌天台赋，胡然遽返真。","法星沉昨夜，仙箓注兹辰。","闽海馀波润，吴江旧业贫。","片心留一剑，洒泪挂松筠。"]},{"t":"挽孙司理 其二","f":"五言律诗","c":["垂虹何处是，归榇但扁舟。","鹤向青城唳，马含白练愁。","琴书孤橐冷，蘋藻五湖秋。","赢得舆人颂，精灵逝不留。"]},{"t":"山行有怀","f":"五言律诗","c":["欲采山中秀，虬髯未可逢。","蓟门违凤啸，郑圃恋仙踪。","云气团岩竹，泉声杂涧松。","暝投何处宿，隔水动疏钟。"]},{"t":"岁暮咏怀兼呈唐明府巫太学诸君 其一","f":"五言律诗","c":["访戴停孤棹，江城岁欲阑。","同云一夜合，积雪四山寒。","落魄诗堪废，愁肠酒转宽。","河阳花渐发，倚杖及春看。"]},{"t":"岁暮咏怀兼呈唐明府巫太学诸君 其二","f":"五言律诗","c":["雨雪空斋暝，萧然此抱疴。","孤篷游已倦，长铗向谁歌。","竹翠侵衣湿，溪声入枕多。","主人能爱客，翻不厌婆娑。"]},{"t":"岁暮咏怀兼呈唐明府巫太学诸君 其三","f":"五言律诗","c":["犬马嗟余齿，蹉跎已古稀。","百年犹转盼，三径讵忘归。","柳色含烟嫩，梅花带雨飞。","乡心逐流水，言采故山薇。"]},{"t":"岁暮咏怀兼呈唐明府巫太学诸君 其四","f":"五言律诗","c":["垂老长为客，淹留愧此身。","如何生白室，偏爱草玄人。","腊酒倾三雅，春盘荐五辛。","故乡千里外，儿女梦中亲。"]},{"t":"元日用元礼韵","f":"五言律诗","c":["乘春初出郭，峡口一亭开。","不为条风暖，何缘缓步来。","鱼翻池上藻，鸟啄涧边梅。","欲倚卢敖杖，翩翩上九垓。"]},{"t":"早春集光严寺","f":"五言律诗","c":["缓步跻山寺，羁心感岁华。","经初翻贝叶，酒已厌椒花。","白发逃方外，青山梦海涯。","何如双树鸟，日夕听三车。"]},{"t":"早春雷?林招集西郊","f":"五言律诗","c":["乘春多载酒，把臂竹林中。","草细沾新雨，池平漾午风。","人家多社曲，鸡犬似新丰。","肯惜如泥醉，劳生叹转蓬。"]},{"t":"早春次吴希晓韵","f":"五言律诗","c":["岁事才三日，寒阴日渐消。","忽寻芳草去，不待美人招。","煮茗初删竹，倾醪更著椒。","春风轻拂柳，未许折柔条。"]},{"t":"雨中排闷兼呈巫维贞 其一","f":"五言律诗","c":["竹径藏春色，兰皋带雨声。","年华方七日，孤客最关情。","薜荔多垂幄，沧浪足濯缨。","田家东作起，何事不归耕。"]},{"t":"雨中排闷兼呈巫维贞 其二","f":"五言律诗","c":["此地逢人日，空斋一雨寒。","如何春已到，转觉路行难。","蓂荚烟初暝，梨花雪欲残。","故园心一片，安得借飞翰。"]},{"t":"雨中排闷兼呈巫维贞 其三","f":"五言律诗","c":["短发不堪把，流光岁已移。","潜鱼忘巨壑，倦鸟托深枝。","风雨貂仍敝，关山雁故迟。","淹留愁不尽，隐几一裁诗。"]},{"t":"雨中排闷兼呈巫维贞 其四","f":"五言律诗","c":["羁栖魂欲断，暮雨不堪闻。","怀土怜王粲，谈玄愧子云。","灯悬金粟影，炉带玉兰薰。","芳草王孙路，何当醉里分。"]},{"t":"送周士龙入粤兼报黄元白陈尔美","f":"五言律诗","c":["寒色拥江天，离魂倍黯然。","有怀多琬琰，相赠岂兰荃。","啸月嶅山顶，停云瘴海边。","同声如有问，生计老逃禅。"]},{"t":"午日分赋得桃印符 其一","f":"五言律诗","c":["綵丝逢令节，仙篆表灵符。","五木精初聚，千门祟已逋。","采莲喧竞渡，斗草艳当垆。","别有潇湘意，临流吊左徒。"]},{"t":"午日分赋得桃印符 其一 悼亡诗为嵇士茂题卷","f":"五言律诗","c":["嵇生竹林士，伉俪系幽情。","神爽窥圆照，肠愁寄短声。","帐中形影在，花下去来轻。","孙楚哀流电，临风泪满缨。"]},{"t":"午日分赋得桃印符 其二","f":"五言律诗","c":["㡩幕凄凉夜，孤灯思不禁。","为云还入梦，奔月亦何心。","气咽凤凰管，香销翡翠衾。","一弹瑶瑟罢，山水动哀音。"]},{"t":"午日分赋得桃印符 其三","f":"五言律诗","c":["菱镜何能掩，兰房此日亲。","金精空坠地，玉树已成尘。","虹断蓝桥魄，云归洛浦神。","幽香还满室，曾是不归人。"]},{"t":"午日分赋得桃印符 其四","f":"五言律诗","c":["一展悼亡卷，悲风飒飒来。","香魂终不返，玉貌转堪猜。","泪竭潘郎句，心怜谢韫才。","鼓盆非不达，五恨总难裁。"]},{"t":"山中避暑和游元封夏日閒居十首 其一","f":"五言律诗","c":["河朔耽名饮，幽栖性所怡。","钩帘时看竹，隐几漫裁诗。","溽暑过三伏，菩提借一枝。","若非同调者，谁结白云期。"]},{"t":"山中避暑和游元封夏日閒居十首 其二","f":"五言律诗","c":["习静来初地，赍粮不满囊。","恒河晴可濯，祗树午偏凉。","已证传灯录，何论辟谷方。","摊经消永日，更宿赞公房。"]},{"t":"山中避暑和游元封夏日閒居十首 其三","f":"五言律诗","c":["垂老猖狂态，当年契若翁。","利名捐物外，贤圣辨杯中。","阴剩门前柳，材留爨下桐。","羲皇何不作，枕石咏南风。"]},{"t":"山中避暑和游元封夏日閒居十首 其四","f":"五言律诗","c":["眷此清凉界，诸天聚火云。","地含秋水碧，岩拥绿苔纹。","龙藏空中见，曹溪定里闻。","幽偏堪养拙，猿鹤若为群。"]},{"t":"山中避暑和游元封夏日閒居十首 其五","f":"五言律诗","c":["何必探沧海，尼珠得比丘。","年虽过牧豕，心已老盟鸥。","纨扇堪题咏，酒杯但拍浮。","斋心浑不染，剥啄厌相求。"]},{"t":"山中避暑和游元封夏日閒居十首 其六","f":"五言律诗","c":["碧树栖群雀，清风咽暮蝉。","登山怜有屐，挂壁笑无弦。","混世青门业，劳生绛县年。","何年超苦海，聊此学逃禅。"]},{"t":"山中避暑和游元封夏日閒居十首 其七","f":"五言律诗","c":["地僻宜消夏，入林已浃旬。","云迷丹壑迥，雨濯绿荷新。","伏枕多尝药，披裘且负薪。","歌声出金石，原宪未全贫。"]},{"t":"山中避暑和游元封夏日閒居十首 其八","f":"五言律诗","c":["刹自前朝建，谁参最上乘。","无生惟佞佛，有发也呼僧。","榻为栖云下，楼因啸月登。","此中元空洞，何爱亦何憎。"]},{"t":"山中避暑和游元封夏日閒居十首 其九","f":"五言律诗","c":["偃蹇松林下，停云有所思。","关山游子梦，风月美人期。","松覆云阴薄，藤垂日影迟。","沉忧何以遣，赖有手中卮。"]},{"t":"山中避暑和游元封夏日閒居十首 其十","f":"五言律诗","c":["乾坤无尽意，长啸辟支巅。","邻父频携酒，官家少索钱。","摘瓜终老圃，种秫仅荒田。","身世甘枯槁，浮名安足传。"]},{"t":"秋日閒居和张隆甫韵 其一","f":"五言律诗","c":["青山吟谢眺，白马赋陈思。","却厌梧桐落，兼闻蟋蟀悲。","才心空自老，古调竟谁期。","若问柴桑计，萧条五柳枝。"]},{"t":"秋日閒居和张隆甫韵 其二","f":"五言律诗","c":["人生非金石，摇落重含情。","林暝萤初度，汀寒雁数声。","科头山欲瘦，濯足水偏清。","枯槁寻常事，安知身后名。"]},{"t":"秋日閒居和张隆甫韵 其三","f":"五言律诗","c":["地僻人稀到，清秋昼掩关。","世随沧海变，心与白云閒。","烟淡萦长薄，林疏出远山。","忽闻樵唱起，鸦带夕阳还。"]},{"t":"秋日閒居和张隆甫韵 其四","f":"五言律诗","c":["万籁空中发，凄凉枕上闻。","道穷元不病，身隐总焉文。","来去澄江月，浮沉薄海云。","垆头无浊酒，何以遣尘氛。"]},{"t":"秋日閒居和张隆甫韵 其五","f":"古风","c":["著屐寻丘壑，乾坤一眺中。","终南多捷径，颍水邈高风。","避世青门拙，问年绛县同。","草?怀耿耿，帝座岂堪通。"]},{"t":"秋日閒居和张隆甫韵 其六","f":"五言律诗","c":["草际沙鸥集，江村事事幽。","才非堪傲世，赋敢附悲秋。","风冷初飘箨，云低半入楼。","无营耽旷达，嵇阮或同流。"]},{"t":"秋日閒居和张隆甫韵 其七","f":"古风","c":["百岁嗟驹隙，无劳较短长。","但?人醉月，莫问鬓沾霜。","道与渔樵狎，情难犬马忘。","诵诗哀岵屺，泪满白云乡。"]},{"t":"秋日閒居和张隆甫韵 其八","f":"五言律诗","c":["一间容膝地，何处想楼台。","土木形全毁，星霜鬓屡催。","飘零荷叶佩，潦倒菊花杯。","不是求羊辈，蓬门莫浪开。"]},{"t":"秋日閒居和张隆甫韵 其九","f":"五言律诗","c":["水天浑一色，彷佛见真吾。","自爱逃空谷，深惭涉畏途。","松风吹草榻，海月挂冰壶。","裘马飞扬态，从他竞五都。"]},{"t":"秋日閒居和张隆甫韵 其十","f":"五言律诗","c":["文园抛绿绮，病渴却为谁。","味似兰初臭，心悲石可移。","南阳龙欲啸，东海钓方垂。","山水知音者，寥寥未有期。"]},{"t":"春日幽居十首和薛景登韵 其一","f":"五言律诗","c":["春风何淡荡，疏拙恋閒居。","一著登山屐，如乘下泽车。","明农忧旱涝，读易悟乘除。","偃蹇从吾道，无劳问索虚。"]},{"t":"春日幽居十首和薛景登韵 其二","f":"五言律诗","c":["科头过岁月，草泽一閒人。","织屦终违俗，卖浆偶比邻。","时名龙卧稳，春梦蝶飞频。","同病怜嵇阮，垆头日可亲。"]},{"t":"春日幽居十首和薛景登韵 其三","f":"五言律诗","c":["浊酒耽陶令，新诗拟惠休。","人惊双鬓短，花簇数枝稠。","负汉终投阁，怀秦独倚楼。","吾惭三老后，曳杖亦名鸠。"]},{"t":"春日幽居十首和薛景登韵 其四","f":"五言律诗","c":["垂钓无他事，沙边繫小舠。","愁肠思蹈海，病色起观涛。","积雾炊烟湿，奔泉激石号。","寰区多震荡，何计定金敖。"]},{"t":"春日幽居十首和薛景登韵 其五","f":"五言律诗","c":["身世看如此，三洲只敝庐。","持斋寒食后，脩禊暮春初。","丘壑孤云迥，琴樽一榻馀。","倦来时隐几，抛却养生书。"]},{"t":"春日幽居十首和薛景登韵 其六","f":"五言律诗","c":["薄暮收鱼笱，呼童掩竹关。","乘风非北牖，步月即东山。","湖海登楼倦，园林抱瓮閒。","美人安可望，厌说落花班。"]},{"t":"春日幽居十首和薛景登韵 其七","f":"五言律诗","c":["几年无战伐，何事亟传烽。","谁借军中箸，长驱海上艟。","檄堪清瘴疠，佩欲解芙蓉。","不尽忧时意，荒村听暮舂。"]},{"t":"春日幽居十首和薛景登韵 其八","f":"五言律诗","c":["岸帻松林下，衔杯水竹前。","清狂非玩世，沉醉近逃禅。","风雨催春色，藤萝逗暝烟。","前身疑毕卓，也作瓮头眠。"]},{"t":"春日幽居十首和薛景登韵 其九","f":"五言律诗","c":["白首机心息，何妨识者稀。","糟丘堪自老，斥鴳岂高飞。","豪侠千金尽，穷愁万事违。","首阳人不作，薄采故山薇。"]},{"t":"春日幽居十首和薛景登韵 其十","f":"五言律诗","c":["悬鹑依陋巷，妻子任长贫。","高蹈怀千古，劳生笑此辰。","乾坤宽荷锸，草莽窃沾巾。","五柳青青色，依然不惹尘。"]},{"t":"寄怀郑景爱","f":"五言律诗","c":["溪流喧入枕，落日漫怀人。","偃蹇俱违俗，艰危各问津。","春从多病过，鬓为苦吟新。","何日囊山社，寻僧重结邻。"]},{"t":"寄游元封","f":"五言律诗","c":["心交淡似水，夙昔别郊坰。","梦断天涯雨，愁多水上萍。","关山遥度雁，节序暗流萤。","若醉江楼月，曾知泽畔醒。"]},{"t":"酬杨伯海见赠","f":"五言律诗","c":["万事皆春梦，浮生枉自劳。","乾坤容此物，湖海傲吾曹。","身后名何益，杯中兴独豪。","醒来行泽畔，寥落楚人骚。"]},{"t":"读方员外浮湘集赋赠 其一","f":"五言律诗","c":["一代文章伯，风流汉子长。","扁舟浮万里，高咏满三湘。","游女捐琼佩，骚人制野裳。","青云词赋色，千载并沧浪。"]},{"t":"读方员外浮湘集赋赠 其二","f":"五言律诗","c":["不读西征赋，谁知大雅吟。","衡山秋色壮，湘水暮云深。","二女重华泪，孤臣众妒心。","应知摇彩笔，山鬼啸空林。"]},{"t":"秋日薜荔园书怀 其一","f":"五言律诗","c":["一帘黄叶雨，高枕白云秋。","天地甘贫病，蓬蒿自去留。","鱼肠空结客，猿臂岂封侯。","所以忘机者，临流狎海鸥。"]},{"t":"秋日薜荔园书怀 其二","f":"五言律诗","c":["悲风鸣大壑，落叶满荒苔。","倦鸟投林尽，浮云度海来。","文章裁短褐，日月寄深杯。","中散交游绝，柴门昼不开。"]},{"t":"秋日薜荔园书怀 其三","f":"五言律诗","c":["一径萋寒卉，孤村逗夕阳。","溪流环远近，树影散池塘。","有客怀餐菊，无人问翳桑。","端居空自好，山际白云翔。"]},{"t":"秋日薜荔园书怀 其四","f":"五言律诗","c":["秋色江村冷，兼之四壁贫。","图书供岁月，牛马任风尘。","蹈海齐高士，怀沙楚逐臣。","吾生空落落，华发几茎新。"]},{"t":"暮秋即事怀许希旦","f":"五言律诗","c":["篱菊还堪把，萧条酒一尊。","吟诗生白发，听鸟到黄昏。","乱竹栖幽径，微云缀远村。","风流高月旦，欲向汝南论。"]},{"t":"秋日访张明府同游山人赋 其一","f":"古风","c":["偃蹇嗟吾党，相过岂世情。","途穷诗作祟，俗薄酒为名。","月朗花阴静，风微竹影清。","百年?一醉，刘阮或同声。"]},{"t":"秋日访张明府同游山人赋 其二","f":"五言律诗","c":["秋气生林薄，扁舟访隐居。","青山生计在，白眼世情疏。","陶令贫耽酒，虞卿老著书。","飞来天外月，不醉欲何如。"]},{"t":"秋日集柯尧叟草堂得斜字","f":"五言律诗","c":["看竹向谁家，柯亭兴不赊。","开尊迎五柳，染翰丽三花。","阁迥云微度，林深日易斜。","猖狂吾党在，月下斗瑶华。"]},{"t":"冬日同游宗谦余思澄泛木兰作 其一","f":"五言律诗","c":["为有寻真兴，欢乘载酒船。","溪寒云翳日，谷迥树浮天。","龙气盘沙岸，鸥群散野田。","共歌招隐赋，挥手弄苍烟。"]},{"t":"冬日同游宗谦余思澄泛木兰作 其二","f":"五言律诗","c":["千秋含朔气，天地有无间。","风送扁舟客，云随孤鸟还。","浮生逃浊酒，高眼傲青山。","胜地藤萝古，游人几醉攀。"]},{"t":"别方子韩 其一","f":"五言律诗","c":["湖海怜同病，风尘笑独醒。","投人双白璧，愤世一青萍。","落魄文章壮，狂歌涕泪零。","鹏抟还尔辈，吾道托鸿冥。"]},{"t":"别方子韩 其二","f":"五言律诗","c":["飘零谁下榻，偃蹇独登楼。","交态黄金变，穷途白发愁。","飞扬裁郢曲，睥睨看吴钩。","莫洒杨朱泪，乾坤一叶舟。"]},{"t":"别方子韩 其三","f":"五言律诗","c":["司马才名大，元龙客礼疏。","形骸长自放，词赋好谁嘘。","把袂看时事，衔杯叹索居。","不知萍梗迹，飘泊竟何如。"]},{"t":"别方子韩 其四","f":"五言律诗","c":["问奇曾载酒，听雨几联床。","久客何萧索，悲歌故慨慷。","竖儒从侧目，世路枉回肠。","我辈风流在，何妨入醉乡。"]},{"t":"别方子韩 其五","f":"五言律诗","c":["才名空落落，踪迹竟栖栖。","骏骨千金妒，羊肠九坂迷。","人从天外别，乌似故乡啼。","莫笑交游绝，前身是姓嵇。"]},{"t":"别方子韩 其六","f":"五言律诗","c":["江湖双别泪，天地一狂生。","有客同王粲，何人称祢衡。","绨袍风雨色，樽酒别离情。","君自怀明月，终偿十五城。"]},{"t":"蚤春陪舅林郡丞暨黄全之许希旦姚体恪体贞兄弟集郑氏北郭别业 其一","f":"五言律诗","c":["春入柳条新，郊游岸角巾。","青山环别业，芳树媚佳辰。","陶谢俱词客，荆高总酒人。","年华驹过隙，欢赏剧相亲。"]},{"t":"蚤春陪舅林郡丞暨黄全之许希旦姚体恪体贞兄弟集郑氏北郭别业 其二","f":"五言律诗","c":["草阁背城开，何人载酒来。","偶因随杖屦，共此破莓苔。","韦曲寻春宴，梁园作赋才。","留连情未已，城角暮声哀。"]},{"t":"白沙谒陈宪副墓","f":"五言律诗","c":["佳气纷沙渚，新阡紫翠中。","停车悲宿草，投辖想高风。","两汉文章色，三吴战伐功。","嗟余后死者，流水恨无穷。"]},{"t":"谒林和靖处士墓","f":"五言律诗","c":["停舟访林壑，猿鸟若为群。","秋色西湖水，前朝处士坟。","山含三竺雨，柳带六桥云。","千古遗踪在，梅花梦见君。"]},{"t":"赠袁景从","f":"五言律诗","c":["袁生禀异姿，偃蹇尚藜藿。","白凤梦常悬，青云名自薄。","悠悠海上鸥，矫矫空中鹤。","为报草玄人，吾今亦寂寞。"]},{"t":"立秋夜呈吴子从","f":"五言律诗","c":["大火西流夕，庭柯一叶飞。","如何萍梗迹，犹与故山违。","白露团芳草，流萤度翠微。","凉风吹客梦，归思共依依。"]},{"t":"酬萧汉卿","f":"五言律诗","c":["览镜惊华发，看花忆故庐。","五湖非范蠡，四壁即相如。","已悔雕虫技，长怀种树书。","行藏君莫问，吾道自樵渔。"]},{"t":"送陈本虞游燕访其弟本容","f":"五言律诗","c":["仗剑辞吾党，翩翩向帝州。","谢家春草梦，易水蓟门秋。","侠气倾三辅，诗名动五侯。","黄金燕市里，早晚索骅骝。"]},{"t":"同游宗谦集马从甫草堂作","f":"五言律诗","c":["清尊开别墅，慷慨命吾徒。","子夜吴歌啭，阳春郢调孤。","凌云名不薄，醉月气何粗。","栗里风流在，重过有酒无。"]},{"t":"寄郑兆采","f":"五言律诗","c":["苦忆谈天客，江城久索居。","山林余小隐，词赋尔长驱。","径草萦书带，岩花映绮疏。","九华悬片月，西望欲踟蹰。"]},{"t":"关山月","f":"五言律诗","c":["上谷风尘起，良人去不归。","青楼多涕泪，紫塞隔音徽。","月下秋砧急，庭前桐叶飞。","榆关万里道，何处寄寒衣。"]},{"t":"泊平浦作","f":"五言律诗","c":["天涯飘泊处，日暮动深情。","身世随蓬转，关山对月明。","西江初挽粟，南粤未休兵。","如此艰难道，非关学请缨。"]},{"t":"沙阳守涨作","f":"五言律诗","c":["积雨溪初涨，孤舟泊水涯。","荒村馀鸟雀，落日走龙蛇。","偃蹇成何事，飘零祗自嗟。","隔林烟火起，暂向酒人家。"]},{"t":"程乡舟中","f":"五言律诗","c":["乘舟来百粤，五月尚披裘。","瘴气晴飞雨，溪风飒似秋。","文章非屈宋，踪迹老穷愁。","此际思乡泪，潺湲水共流。"]},{"t":"雨泊作","f":"五言律诗","c":["西风吹大漠，远客滞归舟。","雨暗城阴色，云含海上愁。","潮声来卧榻，画角起层楼。","那得新丰酒，悠然命马周。"]},{"t":"题竹林七贤图","f":"五言律诗","c":["昔时竹林人，俱是清狂客。","逃名却尚奇，纵酒已成癖。","天地总虚无，老庄与朝夕。","吾生后汝期，感慨兹遗迹。"]},{"t":"题余思澄超然楼次柯尧叟韵","f":"五言律诗","c":["高阁清阴合，乘秋曳履过。","凭轩穷海岳，把酒命羊何。","落日低双鸟，微云淡九河。","悬知占太史，座上德星多。"]},{"t":"雨中登江天阁","f":"五言律诗","c":["积雨依山寺，凭高思渺茫。","潮声回片石，云气暗空廊。","地控南徐险，天连北斗长。","凄凄何处笛，此调是沧浪。"]},{"t":"雨中诸君子携歌者过饮草堂醉后赋此 其一","f":"五言律诗","c":["十日嗟余病，扁舟见汝情。","清秋来旧侣，子夜啭新声。","天地容吾党，文章误此生。","但教千日醉，不必问阴晴。"]},{"t":"雨中诸君子携歌者过饮草堂醉后赋此 其二","f":"五言律诗","c":["何来白眼客，樽酒共留连。","词藻凌三晋，风流恰七贤。","蝉声消暑气，山色带秋烟。","况有何戡在，酣歌五柳前。"]},{"t":"夏日仝陈元甫僧宏恩过万松庵盛仲文读书处得中字","f":"五言律诗","c":["地僻蓬门静，松萝一径通。","薰风回石榻，幽梵出花丛。","问字通扬子，谈经对远公。","兴阑尊酒罢，归路月明中。"]},{"t":"春日仝游宗谦方行渐柯尧滕东山晚眺作","f":"五言律诗","c":["春色在东山，登临紫翠间。","孤城悬落日，双树隐禅关。","草自香台积，僧从下界还。","欲除生灭念，惟与白云閒。"]},{"t":"人日冶城山斋呈吴子从 其一","f":"五言律诗","c":["异地逢人日，空斋滞客星。","愁来双鬓白，病起数峰青。","弱柳矜明媚，飞鸿去杳冥。","途穷休下泪，身世等浮萍。"]},{"t":"人日冶城山斋呈吴子从 其二","f":"古风","c":["紫气秦淮合，钟陵杳霭间。","?知逢七日，又是客三山。","柳色将春到，禽声对酒閒。","故园花渐发，惆怅未言还。"]},{"t":"张子明马一卿过山居有作走笔答之","f":"五言律诗","c":["留滞江东客，何来宿北城。","高斋堪伏枕，浊酒且逃名。","竹径分秋色，松涛杂梵声。","风流非二仲，谁过蒋元卿。"]},{"t":"同蔡真卿余鞠夫登淮阴城","f":"五言律诗","c":["雉堞连云峻，东流楚水深。","以余多感慨，与尔一登临。","春草王孙泪，烟尘国士心。","城边无漂母，谁复饭淮阴。"]},{"t":"秋夜月仝马从甫许希旦方子韩作","f":"五言律诗","c":["霄汉涓涓净，孤轮何处安。","西风吹不堕，永夜此相看。","影入疏林破，光侵草榻寒。","年年一樽酒，憔悴倚阑干。"]},{"t":"安仁夜泊寄立朝立虞诸叔","f":"五言律诗","c":["落魄堪如此，江城又泊船。","星临三楚客，雁断七闽天。","鬓似悲秋白，言非解事玄。","刀头心欲折，谁乞买山钱。"]},{"t":"戊子即事","f":"五言律诗","c":["寥落天涯客，沉吟感慨生。","鱼龙何偃蹇，豺虎亦纵横。","饿莩中原色，仳离故国情。","闾阎忧不细，无计答承明。"]},{"t":"冬夜仝林靖初林方道陈廷选林奉初余伯荐柯世显集郑兆相宅","f":"古风","c":["片月移庭树，花阴客乍来。","张灯娱永夕，促席罄深杯。","歌彻湘中曲，谈倾稷下才。","留连?一醉，肯惜玉山颓。"]},{"t":"同邬汝翼冯咸甫显甫姜元从集于邬先南楼","f":"五言律诗","c":["开尊非北海，作赋自南楼。","即对青山色，难消白发愁。","寒潮喧渡口，落日挂城头。","酩酊狂相傍，乾坤一海鸥。"]},{"t":"西湖同蔡幼公马从甫冯咸甫作","f":"五言律诗","c":["湖天何渺渺，载酒镜中游。","双塔凌云起，孤山抱日流。","香生搴杜佩，歌动采莲舟。","更爱忘机鸟，沧波任去留。"]},{"t":"雨中集游元封双璧堂因怀其尊人宗谦","f":"五言律诗","c":["片雨昼冥冥，入帘书带青。","柳条低结冷，花萼散微馨。","校字乌知学，闻诗鲤过庭。","穷交吴楚别，忽忽七流萤。"]},{"t":"南浦寄黄惟雅","f":"五言律诗","c":["江夏怜新别，论交十载情。","停舟依柘浦，下榻恋芝城。","风雨花间啸，琴樽竹下迎。","即今馀梦寐，隔水听啼莺。"]},{"t":"春夜集黄惟雅草堂仝陈彦宗蓝翰卿作","f":"五言律诗","c":["银烛吐珠光，邀宾醉草堂。","缑山星乍弄，湘浦色初张。","卮进长生酒，诗赓大雅章。","同心厌此夜，漫说少年场。"]},{"t":"舟中怀鞠夫","f":"五言律诗","c":["落日照长川，孤舟思渺然。","江村沧霭外，城郭白云边。","寂寞留玄草，猖狂乏酒钱。","不知之子别，把臂是何年。"]},{"t":"云来阁玩月同陈尧勋陈公衡作","f":"五言律诗","c":["置酒延词客，壶公秀可餐。","欲披云外影，坐待月华看。","河汉金波淡，蟾蜍玉露寒。","若非班氏女，谁解赋齐纨。"]},{"t":"同祖仁甫李得名杨唯光饮谷神观","f":"五言律诗","c":["山馆饶脩竹，风来暑气微。","仙童初进酒，词客且披衣。","江阔云初敛，林深鸟不飞。","上升传此地，藉草醉斜晖。"]},{"t":"同黄叔范饮颜廷渠舟中分得侯字","f":"五言律诗","c":["共上木兰舟，沧波狎野鸥。","寒山环水驿，落日隐城楼。","竹叶倾三斗，鱼鲭薄五侯。","那堪同调者，岁岁动离愁。"]},{"t":"智泉流觞","f":"五言律诗","c":["永和修禊日，胜事至今存。","衣染春云色，杯停曲水痕。","东来千雉合，北望九华尊。","但得兰亭趣，桃源未可论。"]},{"t":"乌石山避暑","f":"五言律诗","c":["灵岩标北郭，下瞰白云乡。","塔影悬初地，松涛落上方。","看云频枕石，闻梵欲依床。","避暑疑河朔，传杯乐未央。"]},{"t":"春日访方子举伯纯诸友南山读书处醉后留题","f":"五言律诗","c":["南山幽僻处，倚杖问僧家。","一径通玄草，双林吐觉花。","春深寒雨细，谷迥暮云斜。","尊酒交欢罢，斋心礼法华。"]},{"t":"登名山寺宿高盖兰若纪兴 其一","f":"五言律诗","c":["出郭饶幽兴，崎岖岭复溪。","千重青嶂合，万顷白云低。","涧水鸣秋雨，田家报午鸡。","篮舆乘偃蹇，端欲问招提。"]},{"t":"登名山寺宿高盖兰若纪兴 其二","f":"五言律诗","c":["南宗初问道，振策陟崔嵬。","宝座参云合，珠帘射日开。","凤停千佛岭，龟傍九莲台。","欲见人天界，临池笑劫灰。"]},{"t":"登名山寺宿高盖兰若纪兴 其三","f":"五言律诗","c":["何处穷蓬岛，孤高有此峰。","飞烟空世眼，积翠洒吾胸。","鸣磬驯檐鸽，谈经起钵龙。","诸天瞻咫尺，佞佛得何颙。"]},{"t":"登名山寺宿高盖兰若纪兴 其四","f":"五言律诗","c":["鹫岭疑兹地，真堪奉法王。","芙蓉云外耸，薝卜雨中香。","山色含晴霭，钟声带夕阳。","下方聊借榻，兰若一灯光。"]},{"t":"题朱医社","f":"五言律诗","c":["吾爱朱公社，壶邱水石凉。","寿齐椿树永，春满橘花香。","宝箓凭云护，灵旗薄日扬。","斋心求服食，隐隐见中黄。"]},{"t":"九鲤湖即事","f":"五言律诗","c":["步入桃源路，山空日未昏。","花明丹灶火，犬吠酒家村。","石窍通鳌极，涛声激海门。","翻思生羽翼，长啸蹑昆崙。"]},{"t":"送立斐叔之延平","f":"五言律诗","c":["朔风日以厉，蹑蹻欲何之。","人与壶山别，舟从剑水移。","九峰堪载酒，八角好裁诗。","倘忆林间竹，归来待几时。"]},{"t":"挽果轩叔 其一","f":"五言律诗","c":["神理冥冥在，凄风断竹林。","泣谁明璞玉，教独费籯金。","秦市舂休杵，雍门响绝琴。","生前徒识汝，酹酒意难禁。"]},{"t":"挽果轩叔 其二","f":"五言律诗","c":["病岂休文似，召胡李贺同。","身名遗草在，世事落花空。","棋墅明凉月，玄亭响夜虫。","攫金曾不理，意气古人中。"]},{"t":"哭王长公 其一","f":"五言律诗","c":["忽报中台折，何人不黯然。","弇山寒旧日，娄水咽新阡。","万象收元气，千秋罢太玄。","生刍陈一束，无计问青天。"]},{"t":"哭王长公 其二","f":"五言律诗","c":["勋业三朝老，文章百代师。","倏为鸿鹄举，长与白云期。","海岳空盟主，衣冠失羽仪。","纵馀山水调，弦断不胜悲。"]},{"t":"哭王长公 其三","f":"五言律诗","c":["商风号大壑，惨淡岁星徂。","神理绵绵在，仙踪渺渺孤。","曲池残雪冷，高馆暮禽呼。","惆怅游梁客，重来泪已枯。"]},{"t":"病中答黄全之","f":"五言律诗","c":["伏枕当春暮，穷愁岂有宽。","腰应疑沈约，鬓已似潘安。","诗草床头废，烟花梦里看。","多君金石赠，病起欲加餐。"]},{"t":"夜雨薛允同至","f":"五言律诗","c":["客舍凄凉夜，孤灯照雨声。","故人来访戴，樽酒坐班荆。","流水怜同调，浮云笑此生。","不须论往事，但耦百年耕。"]},{"t":"严滩上怀王仲房","f":"五言律诗","c":["论交二十载，湖海邈高风。","名自青云薄，诗多白发工。","灵岩探玉笥，流水调丝桐。","七里扁舟客，怀人数断鸿。"]},{"t":"马从甫招饮病中却寄兼呈诸君","f":"五言律诗","c":["故人春酒熟，招我醉烟萝。","不浅衔杯兴，其如伏枕何。","隔帘黄鸟静，当户白云多。","肠断高阳侣，无因共啸歌。"]},{"t":"访陈振狂不值","f":"五言律诗","c":["为爱幽栖客，停舟问草堂。","片云移远树，孤雁带斜阳。","招隐诗空咏，谈玄意不忘。","柴门秋色里，何处采幽芳。"]},{"t":"吴伯时招游北郭同方嗣宗作","f":"五言律诗","c":["邀欢初出郭，选胜属清秋。","但得逍遥趣，何殊汗漫游。","烟云十里澹，花木一庭幽。","共泛杯中物，陶然散客愁。"]},{"t":"过朱宾徵馆中留酌赋赠同冯彝甫作","f":"五言律诗","c":["楚楚陈中彦，明时璧未沽。","图书窥二酉，词赋擅三都。","乍见神偏合，相过兴不孤。","交欢尊酒在，片月映冰壶。"]},{"t":"七夕集社中诸子迟柯陈二孝廉不至得槎字","f":"五言律诗","c":["嘉会当今夕，移樽对藕花。","云霞生满翰，河汉望乘槎。","砧捣千门月，盘堆五色瓜。","风流怀二子，乞巧向谁家。"]},{"t":"新秋寄友人 其一","f":"五言律诗","c":["相思岁华晚，相望海云深。","明月青山梦，秋风白石心。","轩窗倚桂树，道路入枫林。","遥想梅花下，翛然独抱吟。"]},{"t":"新秋寄友人 其二","f":"五言律诗","c":["高柳自鸣蝉，秋风忽洒然。","拟寻东海钓，聊就北窗眠。","芸架有遗帙，草堂无俸钱。","物情关百虑，转觉愧前贤。"]},{"t":"新秋招诸子结社囊山得西字","f":"五言律诗","c":["山中招隐处，浊酒熟堪携。","秋色梧桐下，人烟曲水西。","听蝉依灌木，待月步前溪。","好是莲花社，新诗扫石题。"]},{"t":"怀袁景从","f":"五言律诗","c":["一片云如盖，迢迢忆故人。","西京还献赋，东海漫垂纶。","芳树蝉声晚，空山月色新。","不知文似者，何处混风尘。"]},{"t":"题囊山兰若","f":"五言律诗","c":["习静投山寺，莲花不染心。","孤云团野色，片雨散秋阴。","竹影侵禅榻，松涛杂梵音。","无生如可学，长此卧东林。"]},{"t":"社中诸子访我海上赋此","f":"五言律诗","c":["一区甘寂寞，谁问子云奇。","竹径迎秋早，柴门候客迟。","落霜晴拥树，流水曲通池。","共醉青天月，何妨倒接䍦。"]},{"t":"立秋柬立朝叔","f":"五言律诗","c":["南陆流金日，科头卧北窗。","忽惊秋叶下，暑气薄澄江。","白羽摇云阁，青樽泛钓艭。","风流过小阮，月下倒银缸。"]},{"t":"入苏门","f":"五言律诗","c":["策杖游何处，苏门慕昔贤。","松声疑凤啸，云气似龙潜。","台迥藏修竹，山深拥紫烟。","何当逢石髓，一举挟飞仙。"]},{"t":"送陆使君入觐","f":"五言古诗","c":["万国趋朝日，明堂受计年。","邦家输玉帛，礼乐偃戈鋋。","君是机云后，名高召杜前。","行春蠲井税，折狱挂蒲鞭。","秋水门庭静，冰壶案牍悬。","衣冠趋俎豆，禾黍被原田。","俗美讴歌起，风恬疾苦捐。","潢池应解剑，墨绶但鸣弦。","神雀元堪纪，噩鱼穴乍迁。","七闽推治郡，三殿引朝天。","岭峤初驰驿，江津迥泊船。","观涛经楚越，望日指幽燕。","奏最遵周典，厉精际汉宣。","龙颜瞻咫尺，虎拜舞蹁跹。","鹓鹭班还接，蓼萧赋已传。","黄金誇独赐，赤县梦相牵。","总庆明良会，何惭岳牧贤。","春风驰五马，莫恋洞庭荃。"]},{"t":"夏日登林邦介凉台","f":"五言古诗","c":["树杪凉风发，高台骋望宜。","青山争睥睨，沧海自逶迤。","日月团飞盖，云霄碍接䍦。","夷门公子驾，河朔故人卮。","侠爱纵横客，狂呼大小儿。","长歌回北斗，孤啸振南枝。","笔带晴霞丽，筵开落照迟。","广寒如可蹑，员峤更何之。","不浅登临兴，应刘此一时。"]},{"t":"送林咨伯上春官","f":"五言古诗","c":["挟策上燕京，翩翩万里程。","帆摇扬子渡，雁背越王城。","岁暮风尘色，天涯雨雪声。","乘春偕上计，谒帝入承明。","骏索千金价，科登片玉名。","御堤看弱柳，禁苑听新莺。","谏猎文章丽，凌云气象横。","直窥中秘册，漫请少年缨。","沧海龙初起，丹山凤乍鸣。","柏梁多唱和，莫不寄柴荆。"]},{"t":"咫园篇","f":"五言古诗","c":["名园开咫尺，大隐绝风尘。","啸傲烟霞老，栖迟鬓发新。","桔槔偏不用，杖屦每相亲。","岂是陶弘景，居然郑子真。","盖停邺下客，瓮抱汉阴人。","薜荔裁初服，兰荃若比邻。","柳随彭泽径，花压武陵津。","金谷空争丽，土泉别有春。","丛篁迟凤翮，古柏偃龙鳞。","醒酒时凭石，弹棋或藉茵。","著书淹岁月，染翰乱星辰。","环堵原非病，于陵岂为贫。","当年青琐闼，此日白纶巾。","濠濮生幽想，蓬蒿得隐沦。","何须吞梦泽，差可避嬴秦。","方丈知何处，乾坤寄此身。","招游惟二仲，讵厌往来频。"]},{"t":"巫文学斋中除夜仝卢元礼作","f":"五言古诗","c":["啸傲空斋静，穷阴入夜除。","自怜多偃蹇，何以荅居诸。","犬马怀丘壑，龙蛇任卷舒。","焚香初隐几，剪烛一摊书。","地主纷陈席，儿童递荐蔬。","情深忘酩酊，心折漫踌躇。","晓漏催偏急，孤床梦转虚。","王孙芳草路，明月倍愁余。"]},{"t":"寿邹山卢封君","f":"五言古诗","c":["蓬莱浮佳气，缭绕丽华堂。","采秀烟霞外，承恩日月傍。","五花开杖屦，七叶盛冠裳。","忠孝贻谋远，诗书衍泽长。","盈庭皆国器，清署更仙郎。","卓异传畿甸，貤褒宠帝乡。","宁亲遥戏綵，报主近含香。","海屋添筹历，皇家正栋梁。","占星新献瑞，躔极永呈祥。","桃李春初满，笙歌夜未央。","婆娑龙是杖，潦倒玉为浆。","麋鹿山中侣，鹓鸾天际行。","词裁三祝颂，诗进九如章。","圣代嘉元老，还看荐锡光。"]},{"t":"神应篇为方伯刘公作","f":"五言古诗","c":["潭州有古木，一旦击风雷。","正直神逾壮，丹青像乍开。","普陀移海岛，祗树拥楼台。","云气疑飞佩，潮声觉渡杯。","玉毫观自在，金粟现如来。","变化原非幻，圆通不用猜。","炎精初作祟，力疾久为灾。","白马经声出，青莲药裹裁。","岿然存夏屋，健矣等童孩。","寂灭龙超象，昂藏鹤印苔。","青童飞玉液，元女进金罍。","解脱春生步，皈依劫作灰。","猿猴群习定，鹦鹉故迟回。","王母延年术，更生命世才。","荆涂钟地脉，淮泗引春醅。","诚孝通群帝，勋名播九垓。","蘋蘩光俎豆，鼎鼐和盐梅。","南斗瞻依者，东闽保障哉。","萱庭滋沆瀣，薇省望崔嵬。","燕喜称宜寿，鹰扬矫上台。","风云乘遇合，天地重栽培。","愿拟河清颂，馀波润草莱。"]},{"t":"赠柯四","f":"五言古诗","c":["东山多秀色，之子擅其英。","世业工文史，时名并弟兄。","高台怀索骏，灌木听求莺。","四壁凌云气，三冬映雪情。","有时然太乙，何日谪长庚。","渐展垂天翼，还传掷地声。","谈应高碣石，价已重连城。","岁月嗟投笔，风尘笑请缨。","腰间双剑在，赠尔驾长鲸。"]},{"t":"赋得春深五凤城送方伯文之京","f":"五言古诗","c":["黄道躔霄汉，青阳逗帝畿。","花明千树锦，日丽九重扉。","葱郁萦丹阙，韶华媚紫薇。","仙桃蒸瑞霭，御柳拂晴晖。","燕入雕梁语，莺从绮阁飞。","六龙争夭矫，五柞竞光辉。","雨湿红将绽，烟浓绿渐肥。","玉绳星欲滴，金掌露初晞。","彤陛摇鸣佩，朝霞映彩衣。","长杨誇浩荡，上苑庆芳菲。","词藻推潘岳，才名重陆机。","天颜瞻咫尺，鹓鹭沐音徽。"]},{"t":"春日送立雨叔读书赤桥四首 其一","f":"七言绝句","c":["花发江城二月天，木兰流水赤桥前。","扁舟载得青箱去，扬子亭中日草玄。"]},{"t":"春日送立雨叔读书赤桥四首 其二","f":"七言绝句","c":["柳色阴阴映白塘，沧浪万顷浣花香。","试看刘向传经处，夜夜青藜照草堂。"]},{"t":"春日送立雨叔读书赤桥四首 其三","f":"七言绝句","c":["一瓢春酒听流莺，花外停桡见友生。","醉藉阶前书带草，几回仙掌梦金茎。"]},{"t":"春日送立雨叔读书赤桥四首 其四","f":"七言绝句","c":["汉家见说启青宫，少海谈经诏九重。","此日蓬门须努力，未央鸣佩听晨钟。"]},{"t":"送江参军还金陵 其一","f":"七言绝句","c":["十载京华白发生，归来海上结鸥盟。","长江春水桃花发，又逐孤帆下石城。"]},{"t":"送江参军还金陵 其二","f":"七言绝句","c":["三月杨花扑酒香，扁舟春水别河梁。","销魂漫拟江淹赋，家住金陵亦故乡。"]},{"t":"送江参军还金陵 其三","f":"七言绝句","c":["金阙连云压翠微，先皇敕赐有光辉。","欲随绛节朝元去，目断天心一鹤飞。"]},{"t":"游仙寺","f":"七言绝句","c":["几度探春路不迷，寻僧又过竹林西。","深山尽日无人到，双树阴中一鸟啼。"]},{"t":"赠王弇州先生 其一","f":"七言绝句","c":["一代文章擅国工，弇州四部古谁同。","自从授得刀圭诀，名在丹台玉籍中。"]},{"t":"赠王弇州先生 其二","f":"七言绝句","c":["星罗北斗照乾坤，七子先朝集蓟门。","独拥金仙朝五岳，至今谁不让昆崙。"]},{"t":"赠王弇州先生 其三","f":"七言绝句","c":["词赋流传遍九垓，嵚崎历落见仙才。","若非长史人间住，沧海谁看水一杯。"]},{"t":"赠王弇州先生 其四","f":"七言绝句","c":["斋心日礼上清家，王母书传萼绿华。","欲拜下风称弟子，鍊成勾漏旧丹砂。"]},{"t":"赠王弇州先生 其五","f":"古风","c":["诏起西曹法从班，殷勤累疏乞东山。","谢公总系苍生望，?得明时但闭关。"]},{"t":"赠王弇州先生 其六","f":"七言绝句","c":["丝纶日下九重频，耆德三朝重老臣。","若学五湖游不返，汉家谁复画麒麟。"]},{"t":"赠王弇州先生 其七","f":"七言绝句","c":["神如秋水映芙蓉，懒著朝衣听晓钟。","笑问仙风谁得似，茅家兄弟跨双龙。"]},{"t":"题立朝叔亭子 其一","f":"七言绝句","c":["一庭春色报芳菲，酒熟床头鳜乍肥。","但得看花频中酒，百年长制薜萝衣。"]},{"t":"题立朝叔亭子 其二","f":"七言绝句","c":["座上青山一片孤，夜来月白似冰壶。","接䍦倒著如泥醉，不管傍人说酒徒。"]},{"t":"题立朝叔亭子 其三","f":"七言绝句","c":["白眼猖狂避世心，蓬池谁解阮公吟。","仲容亦是逃名者，浊酒相看竹下斟。"]},{"t":"赠汪鲁狂","f":"七言绝句","c":["仙人跨鹤下黄山，曳杖逍遥天地间。","曾采三花栖少室，即今白发驻红颜。"]},{"t":"剑浦对月呈陈观甫","f":"七言绝句","c":["津口潺湲万壑哀，城头玉女弄珠来。","依然狱底双龙剑，千载何人复姓雷。"]},{"t":"春暮留云阁感怀 其一","f":"七言绝句","c":["二月花间黄鸟啼，看花人去草萋萋。","白云犹似能留客，一片飞来雨石西。"]},{"t":"春暮留云阁感怀 其二","f":"七言绝句","c":["东山春色挂城头，依旧云霞槛外浮。","别墅弹棋声寂寂，羊昙双泪为谁流。"]},{"t":"春暮留云阁感怀 其三","f":"七言绝句","c":["乌石山前草阁孤，风流曾集竹林徒。","重来多少伤心事，眼底山河邈酒垆。"]},{"t":"春日寄怀陆使君 其一","f":"七言绝句","c":["郡阁三年集凤凰，颍川经术汉循良。","翩翩车骑趋朝日，共识司徒旧省郎。"]},{"t":"春日寄怀陆使君 其二","f":"七言绝句","c":["桑柘春生十万家，蓼萧赐燕日光华。","闽南父老应相慰，行雨还来太守车。"]},{"t":"春日寄怀陆使君 其三","f":"七言绝句","c":["木兰陂上麦如云，露冕风流忆使君。","一自单车俄入郡，讴歌何处不相闻。"]},{"t":"春日寄怀陆使君 其四","f":"七言绝句","c":["计吏从容下建章，紫衣春染御炉香。","乘风若渡巴陵水，莫为江鱼恋武昌。"]},{"t":"春日寄怀陆使君 其五","f":"七言绝句","c":["白雪泠泠和者稀，郢中云树望依微。","汉阳春水茫茫绿，何处仙帆一片飞。"]},{"t":"怀柯尧锡","f":"七言绝句","c":["文藻翩翩锦不如，江湖风雨怅离居。","长卿不是临邛客，谁向云霄荐子虚。"]},{"t":"赠林敷毅 其一","f":"七言绝句","c":["何人意气薄青云，公子翩翩独有君。","客到高斋频下榻，一尊风雨细论文。"]},{"t":"赠林敷毅 其二","f":"七言绝句","c":["楚楚声华动五陵，清标直似玉壶冰。","交游不少纵横客，最爱风流御李膺。"]},{"t":"雨中招廷珍","f":"七言绝句","c":["细雨飘来二月花，美人何处斗豪华。","囊中剩有青铜在，迟尔南邻卖酒家。"]},{"t":"送蔡比部 其一","f":"七言绝句","c":["才名矫矫擅谈天，瘴海风尘谪几年。","憔悴无劳渔父问，三闾心事总堪怜。"]},{"t":"送蔡比部 其二","f":"七言绝句","c":["天涯犹自梦鹓班，彭蠡风高一雁还。","行色萧条无长物，逢人但说武夷山。"]},{"t":"题南山寺","f":"古风","c":["山色迎人兴不孤，白云片片散浮屠。","一尊浊酒?沉醉，箕踞山间听鹧鸪。"]},{"t":"和郑给舍七夕对雨 其一","f":"七言绝句","c":["木叶萧萧送雨声，明河风浪暗中生。","人间尽道天孙巧，机杼空含此夜情。"]},{"t":"和郑给舍七夕对雨 其二","f":"七言绝句","c":["飞来暮雨妒婵娟，隔岁星期一水悬。","却恨云间青鸟使，衔书不向月中传。"]},{"t":"丰城舟中有感","f":"七言绝句","c":["城下江流带夕晖，城边云树望依微。","当年狱底雌雄剑，不识今从何处飞。"]},{"t":"赠陈尧勋云来阁 其一","f":"七言绝句","c":["梅峰山下草堂清，书带参差绕砌生。","一自青藜分太乙，彩毫何处不纵横。"]},{"t":"赠陈尧勋云来阁 其二","f":"七言绝句","c":["结屋壶公兴有馀，满床堆得读残书。","即今不尽南阳泪，云满空山一草庐。"]},{"t":"题翠漪亭","f":"七言绝句","c":["草阁玲珑俯碧池，翠云低压万年枝。","床头浊酒葡萄色，醉倒山公白接䍦。"]},{"t":"别林及甫 其一","f":"七言绝句","c":["岁暮相逢雨雪多，春风曾奈别离何。","解衣不为垆头酒，白眼看人一醉歌。"]},{"t":"别林及甫 其二","f":"七言绝句","c":["按剑风尘祗自愁，嗟君也敝黑貂裘。","怀中十五连城璧，不是相知未可投。"]},{"t":"题元妙观五松","f":"七言绝句","c":["谁种长松礼斗坛，五株曾否拜秦官。","凉风吹上松梢月，影落龙鳞片片寒。"]},{"t":"赠别陈本容 其一","f":"七言绝句","c":["东风乍转柳条新，尔去重扬蓟北尘。","击筑若逢屠狗者，酒中谁是和歌人。"]},{"t":"赠别陈本容 其二","f":"七言绝句","c":["陈遵结侠起高名，尺牍题来慰友生。","不比当年惊座者，风流到处动公卿。"]},{"t":"赠别陈本容 其三","f":"七言绝句","c":["囊里惟藏鸟篆文，江湖谁不识夫君。","北游燕赵南吴楚，奇字偏劳问子云。"]},{"t":"赠别陈本容 其四","f":"七言绝句","c":["笔阵相传自永和，右军书法更谁过。","黄庭写赠清狂客，不为山阴换白鹅。"]},{"t":"赠别陈本容 其五","f":"七言绝句","c":["沽来浊酒意如何，半醉当筵一放歌。","江上千条彭泽柳，不知曾似客愁多。"]},{"t":"赠别陈本容 其六","f":"七言绝句","c":["桃花美酒醉名姬，裘马长安二月时。","妻子鹿门归自好，天涯风雨莫教迟。"]},{"t":"题清樾轩","f":"七言绝句","c":["结得高斋赋考槃，林间新著竹皮冠。","白云犹带苍梧色，散作清阴六月寒。"]},{"t":"袁使君平寇歌 其一","f":"七言绝句","c":["南国烽烟拥二酋，皖城千雉望旄头。","地当三辅惊多垒，谁向军中借箸筹。"]},{"t":"袁使君平寇歌 其二","f":"七言绝句","c":["幕府临戎气拔旌，欃枪入夜照连营。","佩刀直抵沙中去，誓斩鲸鲵一洗兵。"]},{"t":"袁使君平寇歌 其三","f":"七言绝句","c":["潢池何事弄干戈，陈汉山中啸聚多。","不是使君承庙略，居人曾奈麦秋何。"]},{"t":"袁使君平寇歌 其四","f":"七言绝句","c":["天柱崔嵬控上游，长江东下堑皇州。","荆舒一战鞬櫜卧，南顾无劳圣主忧。"]},{"t":"袁使君平寇歌 其五","f":"七言绝句","c":["绿林扫尽凯歌还，父老壶浆皖水边。","见说禁中思颇牧，试看勋业上凌烟。"]},{"t":"义帝陵","f":"七言绝句","c":["牧羊何意起民间，祸隐当年遣入关。","千古兴亡君莫问，江东曾见一人还。"]},{"t":"望庐山","f":"七言绝句","c":["庐岳崚嶒五老峰，鄱阳秋水浸芙蓉。","凌风欲挟飞鸾去，坐听天池万壑钟。"]},{"t":"赠别吴文中 其一","f":"七言绝句","c":["逍遥初谒武夷君，玉女峰头弄白云。","归去扁舟图九曲，幔亭仙乐夜深闻。"]},{"t":"赠别吴文中 其二","f":"七言绝句","c":["南国山川似洛中，官桥截海驾长虹。","蛎螃正美新荔熟，系马垆头醉晚枫。"]},{"t":"赠别吴文中 其三","f":"七言绝句","c":["黄花采采报重阳，人在天涯忆帝乡。","貌得西方金粟影，大江东去泛慈航。"]},{"t":"赠别吴文中 其四","f":"七言绝句","c":["吴郎归骑入长干，窈窕佳人咏合欢。","若问荔枝何所似，胭脂香染水晶寒。"]},{"t":"象教精舍为孔阳宗作","f":"七言绝句","c":["金仙何日至西方，七宝林开古豫章。","见说自焚三昧火，至今时现玉毫光。"]},{"t":"寄吴任德","f":"七言绝句","c":["溪流日暮锁寒烟，石马桥头夜泊船。","不识名园开曲水，怀人几度对婵娟。"]},{"t":"金陵曲四首赠大司马吴公 其一","f":"七言绝句","c":["秣陵宫阙旧长安，车骑如云拥汉官。","司马勋名深帝眷，貔貅千万独登坛。"]},{"t":"金陵曲四首赠大司马吴公 其二","f":"七言绝句","c":["石头虎踞壮金城，江左仍屯七校兵。","樽俎从容多妙略，楼船十万净长鲸。"]},{"t":"金陵曲四首赠大司马吴公 其三","f":"七言绝句","c":["郁郁钟山王气高，长江天堑北通漕。","吴公身系干城寄，钟鼎何论汗马劳。"]},{"t":"金陵曲四首赠大司马吴公 其四","f":"七言绝句","c":["秦淮水接海门潮，北望燕山似九霄。","文武东南功第一，尚方剑履赐趋朝。"]},{"t":"寄黄明府","f":"七言绝句","c":["溪水泠泠日欲斜，孤蓬晚泊乱啼鸦。","不知三径行吟处，犹有东篱未吐花。"]},{"t":"望苏门","f":"七言绝句","c":["黄河中断太行山，一望烟云缥缈间。","欲问苏门鸾凤啸，即今惟有水潺湲。"]},{"t":"大田道中怀孟担","f":"七言绝句","c":["几湾流水咽涓涓，五虎山青马首悬。","欲访故人过峡口，南鸿犹自带风烟。"]},{"t":"渡峡寄尧衢","f":"七言绝句","c":["峡江片片锦帆开，谁抱凌云作赋才。","迟尔凤凰山下客，乘风还上钓龙台。"]},{"t":"范子受宅赏牡丹","f":"七言绝句","c":["谁家亭榭似平章，花媚东风冠洛阳。","客到但倾光禄酒，扑衣何处不天香。"]},{"t":"咏荔枝","f":"七言绝句","c":["绛囊颗颗隐珠胎，不向风尘驰骑来。","自劈凝脂沉碧水，大秦明月掌中回。"]},{"t":"寄沈灵翊","f":"七言绝句","c":["片月亭亭挂碧霄，扁舟夜趁海门潮。","风流何处思公子，寒倚花前斗柳腰。"]},{"t":"题立雨叔餐秀园 其一","f":"七言绝句","c":["春生薜荔翠交加，高捲湘帘览物华。","一曲溪流堪濯锦，有时流出武陵花。"]},{"t":"题立雨叔餐秀园 其二","f":"七言绝句","c":["竹香细细午风柔，高枕沧浪事事幽。","散帙挥毫过白日，嘤嘤灌木鸟相求。"]},{"t":"题立雨叔餐秀园 其三","f":"七言绝句","c":["一室多藏小酉书，草名书带满庭除。","夜来太乙高相照，彩笔如椽赋子虚。"]},{"t":"题立雨叔餐秀园 其四","f":"七言绝句","c":["浊酒谁知大阮心，蓬池无日不清吟。","仲容亦有衔杯兴，散发频来醉竹林。"]},{"t":"春日送家大阮读书城中","f":"七言绝句","c":["春风拂面意何如，柳色黄金映别裾。","十里江城从此去，枕边惟有伏生书。"]},{"t":"马用调草堂观妓 其一","f":"七言绝句","c":["园林寒色淡平芜，公子邀欢兴不孤。","一片烟波清似镜，不知载酒在西湖。"]},{"t":"马用调草堂观妓 其二","f":"七言绝句","c":["高阁临流锦席开，一时词客共徘徊。","雕阑徙倚看山遍，笑折黄花进酒杯。"]},{"t":"马用调草堂观妓 其三","f":"七言绝句","c":["红粉当筵斗绮罗，楼台倒影漾微波。","池头双鹤声相和，似解佳人白苧歌。"]},{"t":"马用调草堂观妓 其四","f":"七言绝句","c":["一林脩竹护柴门，城市栖迟似远村。","但得三千珠履客，不妨十日醉平原。"]},{"t":"经白鸥园有感","f":"七言绝句","c":["池塘依旧隐渔矶，竹径兰皋车马稀。","黄犬无劳伤往事，钤山惟有白云飞。"]},{"t":"秣陵逢孙子真感其先酒楼事赋而赠之","f":"七言绝句","c":["江左佳人说莫愁，逢君慷慨问垆头。","六朝胜迹无寻处，湖上犹传旧酒楼。"]},{"t":"题程君衡扇面","f":"七言绝句","c":["桃花似斗美人妆，掌上看来兴未央。","翠羽却怜春色好，欲衔花片报刘郎。"]},{"t":"赠吴应祈 其一","f":"七言绝句","c":["囊里多藏汲冢文，有时独运郢人斤。","但看赑负千秋色，奇字何劳问子云。"]},{"t":"赠吴应祈 其二","f":"七言绝句","c":["吴楚名山快遍游，瑶华何处不雕锼。","狂来欲借成风手，勒牍仙人十二楼。"]},{"t":"题沈纯甫绿萝庄 其一","f":"七言绝句","c":["疏乞还山别汉都，知君踪迹寄菰蒲。","徙陶偏笑鸱夷策，何似君家长五湖。"]},{"t":"题沈纯甫绿萝庄 其二","f":"七言绝句","c":["岂为长生赋采芝，二毛心事少人知。","沈郎不问腰消瘦，兴到还裁八咏诗。"]},{"t":"题沈纯甫绿萝庄 其三","f":"七言绝句","c":["岭海当年谪戍身，归来旧业白云贫。","一区寂寞玄堪草，载酒时来问字人。"]},{"t":"题沈纯甫绿萝庄 其四","f":"古风","c":["结?此地意如何，书闻名山副墨多。","才见条桑蚕事起，西湖又听采菱歌。"]},{"t":"题武彝 其一","f":"七言绝句","c":["骑来竹杖似飞龙，欲乞金丹访赤松。","三十六峰青不断，仙人何处采芙蓉。"]},{"t":"题武彝 其二","f":"七言绝句","c":["溪上扁舟鸥鹭群，凌风初谒武夷君。","幔亭深处松涛起，彷佛钧天隔水闻。"]},{"t":"题武彝 其三","f":"七言绝句","c":["溪流九曲漾霞标，路入桃源一水遥。","忽听云间吹玉笛，鸾舆飞度綵虹桥。"]},{"t":"题武彝 其四","f":"七言绝句","c":["采秀朝来汗漫游，松风五月冷龙湫。","山中道士如相识，骑鹤招余到十洲。"]},{"t":"题武彝 其五","f":"七言绝句","c":["寻真直到上清家，小藏峰头对月华。","仙分吾生应不薄，亲承玉女饭胡麻。"]},{"t":"题武彝 其六","f":"七言绝句","c":["烟霞五色幻仙台，瑶草千年碧洞开。","一自仙人分石髓，乘风万里去还来。"]},{"t":"晚晀","f":"七言绝句","c":["竹林秋色入黄昏，溪水新添雨后痕。","明月不来人语寂，数家渔火点江村。"]},{"t":"送陈叔理之会稽 其一","f":"七言绝句","c":["谈经遥向越王台，纱浣西施绛帐裁。","若到稽山探禹穴，千年蝌蚪破莓苔。"]},{"t":"送陈叔理之会稽 其二","f":"七言绝句","c":["兰亭曲水试经过，祓禊相传晋永和。","写得黄庭经一卷，山阴明日又笼鹅。"]},{"t":"题九鲤湖九首 其一 雷轰","f":"七言绝句","c":["水晶宫殿压青山，隔断红尘霄汉间。","湖上雷声轰不住，长疑仙子驾龙还。"]},{"t":"题九鲤湖九首 其二 瀑布","f":"七言绝句","c":["寒泉泻下紫霄来，一道潺湲万壑哀。","可是仙人遗匹练，至今犹挂白云隈。"]},{"t":"题九鲤湖九首 其三 珠帘","f":"七言绝句","c":["一片珠帘障玉楼，垂虹为带月为钩。","怪来不作寻常梦，鸾鹤分明到十洲。"]},{"t":"题九鲤湖九首 其四 玉柱","f":"七言绝句","c":["仙人何处弄烟霞，十二楼台别有家。","依旧当年双玉柱，擎天半倚白云斜。"]},{"t":"题九鲤湖九首 其五 石门","f":"七言绝句","c":["双扉寂寂护苍苔，几片浮云洞口来。","笑探三花从此去，不知何处是天台。"]},{"t":"题九鲤湖九首 其六 五星","f":"七言绝句","c":["悬崖千树昼冥冥，一片潭光聚五星。","我欲斋心看道箓，移来午夜照疏棂。"]},{"t":"题九鲤湖九首 其七 飞凤","f":"七言绝句","c":["何物沉冥不可招，九苞曾说跨王乔。","只因误啄金丹粒，谪落人间听玉箫。"]},{"t":"题九鲤湖九首 其八 棋枰","f":"七言绝句","c":["仙子乘龙去不还，棋枰犹自阁人间。","不知千载烂柯后，又著蓬莱第几山。"]},{"t":"题九鲤湖九首 其九 将军","f":"七言绝句","c":["辟谷仙人不可从，云山彷佛武夷踪。","将军不是封侯骨，也学文成访赤松。"]},{"t":"剑浦夜泊","f":"七言绝句","c":["睥睨飞来片月孤，扁舟何处问当垆。","寒潭水冷双龙伏，犹有丰城剑气无。"]},{"t":"寄沙门心印","f":"七言绝句","c":["一别头陀意万重，白云何处寄禅踪。","梦中不辨长千里，犹记山门一古松。"]},{"t":"明妃曲 其一","f":"七言绝句","c":["燕支一望白云秋，马上红颜双泪流。","雁自南飞人北去，琵琶不解汉宫愁。"]},{"t":"明妃曲 其二","f":"七言绝句","c":["北风吹雪暗天山，憔悴蛾眉去不还。","薄命便教边地老，归魂应度玉门关。"]},{"t":"明妃曲 其三","f":"七言绝句","c":["朝辞合殿暮交河，泪满宫衣泻素波。","顾影自怜肠欲断，长门幽怨较谁多。"]},{"t":"明妃曲 其四","f":"七言绝句","c":["青海寒云散作风，谁怜粉黛逐飞蓬。","亭亭一片中天月，彷佛清光照汉宫。"]},{"t":"春日口占","f":"七言绝句","c":["春风昨夜到渔家，江曲濛濛细雨斜。","可怪宅边桃李树，朝来不语自开花。"]},{"t":"题李孚台白水亭 其一","f":"七言绝句","c":["万顷烟霞一草亭，开樽醉杀柳条青。","停杯试问沧浪水，龙卧寒潭几日醒。"]},{"t":"题李孚台白水亭 其二","f":"七言绝句","c":["湖上何来碧浪高，雷轰风猛怒相号。","任公不是寻常手，欲下沧溟钓六鳌。"]},{"t":"送李太守归乡 其一","f":"七言绝句","c":["郭外曾随竹马迎，春风何事动离情。","不堪误得中山谤，归与沙鸥结旧盟。"]},{"t":"送李太守归乡 其二","f":"七言绝句","c":["参差柳色映旌旗，冠盖如云献酒卮。","莫怪萋菲成贝锦，六宫自古妒蛾眉。"]},{"t":"送李太守归乡 其三","f":"七言绝句","c":["宦游踪迹漫西东，参破元机万劫空。","留得甘棠春勿剪，木兰陂上一壶公。"]},{"t":"送李太守归乡 其四","f":"古风","c":["文藻风流似李邕，下车偏自问龙钟。","若非雨露沾枯槁，?得寒山数亩松。"]},{"t":"送李太守归乡 其五","f":"七言绝句","c":["萋萋芳草怨王孙，风雨千山暗泪痕。","兰佩自怜缘帝子，江潭心事许谁论。"]},{"t":"送李太守归乡 其六","f":"七言绝句","c":["花间睍睆啭黄鹂，彭蠡风高片席移。","别后相思千里月，投珠无计转堪悲。"]},{"t":"送李太守归乡 其七","f":"七言绝句","c":["郡斋下凤颍川同，失马无劳叹塞翁。","阶下凌云丛桂发，天香高占广寒宫。"]},{"t":"送李太守归乡 其八","f":"七言绝句","c":["拂衣归去鬓如班，草得玄经合闭关。","多少匡时筹未展，还看安石起东山。"]},{"t":"夜合花","f":"七言绝句","c":["风动香飘十二栏，雨中相对一尊残。","玉容莫向黄昏敛，正欲携灯醉后看。"]},{"t":"雨中杜鹃花","f":"七言绝句","c":["何来杜宇叶离离，三月当庭花满枝。","莫是啼魂哀帝子，至今香染湿胭脂。"]},{"t":"白莲","f":"七言绝句","c":["一朵芙蕖百和香，华清浴罢试新妆。","幽姿自分无泥滓，不用临风妒六郎。"]},{"t":"题画兰赠张子升","f":"七言绝句","c":["萋萋萧艾岂为群，秀色曾从九畹分。","采得芳菲堪作佩，临风只合赠湘君。"]},{"t":"画竹","f":"七言绝句","c":["太湖石畔竹阴阴，影动凉飙曳玉吟。","莫问渭川千亩处，蓬蒿一径白云深。"]},{"t":"画菊","f":"七言绝句","c":["采采黄花浥露香，眼中彷佛对柴桑。","风流谁送先生酒，共坐南山醉夕阳。"]},{"t":"吊屈大夫","f":"七言绝句","c":["汨罗江畔草萧疏，千古怀沙恨有馀。","日暮哀猿正凄切，不知何处吊三闾。"]},{"t":"许由墓","f":"七言绝句","c":["平原四望草离离，箕颍风高见石碑。","不是当年轻万乘，一坏千载有谁知。"]},{"t":"悼内 其一","f":"七言绝句","c":["绣佛斋中梦乍醒，悲风吹月透疏棂。","莲花不见参禅者，冷落床头数卷经。"]},{"t":"悼内 其二","f":"古风","c":["高楼无复试红妆，尘掩香奁泪涕滂。","窃药便教奔月去，广寒?得画眉郎。"]},{"t":"悼内 其三","f":"七言绝句","c":["一夜愁来鬓有丝，吹箫人去见无期。","悼亡不尽潘安泪，忍读生前幼妇词。"]}]};